type Page = 'Resumen'|'Centro de control'|'Vista general'|'Movimientos'|'Cierres de caja'|'Inventario global'|'Sucursales'|'Usuarios'|'Punto de venta'|'Productos'|'Compras'|'Clientes'|'Caja'|'Estado de resultados'|'Reportes'|'Configuración'
const nav: {name:Page;icon:any}[] = [
  {name:'Resumen',icon:LayoutDashboard},{name:'Centro de control',icon:BarChart3},{name:'Punto de venta',icon:ShoppingCart},{name:'Productos',icon:Package},{name:'Compras',icon:Truck},{name:'Clientes',icon:Users},{name:'Caja',icon:WalletCards},{name:'Estado de resultados',icon:ReceiptText},{name:'Reportes',icon:BarChart3}
]
const corporateNav:{name:any;icon:any}[]=[{name:'Vista general',icon:LayoutDashboard},{name:'Estado de resultados',icon:ReceiptText},{name:'Movimientos',icon:RefreshCw},{name:'Cierres de caja',icon:ReceiptText},{name:'Control de caja corporativo',icon:WalletCards},{name:'Inventario global',icon:Boxes},{name:'Asistencia',icon:CalendarDays},{name:'Sucursales',icon:Store},{name:'Usuarios',icon:Users}]
const access:Record<string,Page[]>={admin:['Resumen','Centro de control','Punto de venta','Productos','Compras','Clientes','Caja','Estado de resultados','Reportes','Configuración'],supervisor:['Resumen','Centro de control','Punto de venta','Productos','Compras','Clientes','Caja','Estado de resultados','Reportes'],cashier:['Resumen','Punto de venta','Clientes','Caja'],warehouse:['Resumen','Productos','Compras']}
const canSee=(role:string|undefined,page:Page)=>!role||access[role]?.includes(page)
const roleLabel=(role:string|undefined)=>({admin:'Administrador central',supervisor:'Supervisor',cashier:'Cajero',warehouse:'Bodega'}[role??'']??'')
type CorporateView='overview'|'movements'|'cashClosures'|'cashControl'|'inventory'|'attendance'|'branches'|'team'
const corporateViews:Record<string,CorporateView>={'Vista general':'overview','Movimientos':'movements','Cierres de caja':'cashClosures','Control de caja corporativo':'cashControl','Inventario global':'inventory','Asistencia':'attendance','Sucursales':'branches','Usuarios':'team'}
const corporateView=(page:Page|string)=>corporateViews[page]

export default function App(){
  const [session,setSession]=useState<Session|null>(null)
  const [authReady,setAuthReady]=useState(!isSupabaseConfigured)
  const [passwordSetup,setPasswordSetup]=useState(false)
  const attendanceToken=new URLSearchParams(window.location.search).get('attendance')
  const attendanceQrV2Token=window.location.pathname.startsWith('/asistencia/qr/')?decodeURIComponent(window.location.pathname.replace('/asistencia/qr/','')):new URLSearchParams(window.location.search).get('attendanceQrV2')
  const attendanceReaderV2Token=window.location.pathname.startsWith('/asistencia/lector/')?decodeURIComponent(window.location.pathname.replace('/asistencia/lector/','')):new URLSearchParams(window.location.search).get('attendanceReaderV2')
  const attendanceReaderV3Token=window.location.pathname.startsWith('/asistencia/v3/lector/')?decodeURIComponent(window.location.pathname.replace('/asistencia/v3/lector/','')):new URLSearchParams(window.location.search).get('attendanceReaderV3')
  useEffect(()=>{
    if(!supabase)return
    const invited=window.location.search.includes('invite=1')||window.location.hash.includes('type=invite')||window.location.hash.includes('type=recovery')
    setPasswordSetup(invited)
    supabase.auth.getSession().then(({data})=>{setSession(data.session);setAuthReady(true)})
    const {data}=supabase.auth.onAuthStateChange((_event,next)=>setSession(next))
    return()=>data.subscription.unsubscribe()
  },[])
  if(attendanceReaderV3Token)return <AttendanceReaderV3Public token={attendanceReaderV3Token}/>
  if(attendanceReaderV2Token)return <AttendanceReaderV2Public token={attendanceReaderV2Token}/>
  if(attendanceQrV2Token)return <AttendanceQrV2Public token={attendanceQrV2Token}/>
  if(attendanceToken)return <AttendanceKiosk token={attendanceToken}/>
  if(!authReady)return <div className="app-loading"><div className="brand-mark"><Store/></div><span>Cargando MUNDO MEGA...</span></div>
  if(isSupabaseConfigured&&!session)return <AuthScreen/>
  if(isSupabaseConfigured&&session&&passwordSetup)return <PasswordSetup done={()=>{window.history.replaceState({},'',window.location.origin);setPasswordSetup(false)}}/>
  return <AuthenticatedApp/>
}

function AuthenticatedApp(){
  const [page,setPage]=useState<Page>('Resumen'); const [mobile,setMobile]=useState(false)
  const [catalog,setCatalog]=useState<Product[]>([]); const [profile,setProfile]=useState<StoreProfile|null>(null); const [storeError,setStoreError]=useState(''); const [initialRouted,setInitialRouted]=useState(false);const [platformAdmin,setPlatformAdmin]=useState(false);const [portal,setPortal]=useState<'loading'|'platform'|'business'>('loading')
  const refresh=async()=>{try{const data=await loadStore();setProfile(data.profile);setCatalog(data.products);setStoreError('')}catch(e){setStoreError(e instanceof Error?e.message:'No fue posible cargar los datos')}}
  useEffect(()=>{Promise.all([refresh(),checkPlatformAdmin()]).then(([,isAdmin])=>{setPlatformAdmin(isAdmin);setPortal(isAdmin?'platform':'business')}).catch(e=>{setStoreError(e instanceof Error?e.message:'No fue posible iniciar');setPortal('business')})},[])
  useEffect(()=>{if(profile&&!initialRouted){if(profile.role==='admin')setPage('Vista general');setInitialRouted(true)}},[profile,initialRouted])
  if(portal==='loading')return <div className="app-loading"><div className="brand-mark"><Store/></div><span>Preparando tu espacio…</span></div>
  if(platformAdmin&&portal==='platform')return <PlatformAdminPortal enterBusiness={()=>setPortal('business')}/>
  if(profile&&!profile.active)return <main className="auth-page"><section className="auth-form-wrap"><div className="auth-form"><span className="eyebrow">CUENTA INACTIVA</span><h2>Acceso suspendido</h2><p>Tu usuario esta inactivo. Solicita reactivacion a un administrador.</p><button className="auth-submit" onClick={()=>supabase?.auth.signOut()}>Cerrar sesion</button></div></section></main>
  if(profile?.forcePasswordChange)return <PasswordSetup clearForce done={()=>refresh()}/>
  return <div className="app-shell">
    <aside className={mobile?'sidebar open':'sidebar'}>
      <div className="brand"><div className="brand-mark"><Store size={22}/></div><div><b>Grupo Multimarkets S.A.</b><span>MUNDO MEGA</span></div><button className="mobile-close" onClick={()=>setMobile(false)}><X/></button></div>
      {profile?.role==='admin'?<div className="corporate-side-label"><BarChart3/><div><small>Portal activo</small><strong>Centro corporativo</strong></div></div>:<BranchSwitcher profile={profile} refresh={refresh}/>}
      <nav>{(profile?.role==='admin'?corporateNav:nav.filter(n=>canSee(profile?.role,n.name))).map(n=><button key={n.name} className={page===n.name?'active':''} onClick={()=>{setPage(n.name);setMobile(false)}}><n.icon size={19}/><span>{n.name}</span>{n.name==='Productos'&&<em>3</em>}</button>)}</nav>
      <div className="side-bottom">{platformAdmin&&<button className="platform-return" onClick={()=>setPortal('platform')}><Globe2/><span>Panel multiempresa</span></button>}<div className="profile"><div className="avatar">{profile?.fullName?.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()??'--'}</div><div><strong>{profile?.fullName??'Cargando…'}</strong><span>{roleLabel(profile?.role)}</span></div><button className="profile-logout" title="Cerrar sesión" onClick={()=>supabase?.auth.signOut()}><LogOut size={16}/></button></div></div>
    </aside>
    {mobile&&<div className="backdrop" onClick={()=>setMobile(false)}/>}
    <main><Topbar title={page} openMenu={()=>setMobile(true)}/><div className="page-content">
      {storeError&&<div className="system-alert"><AlertTriangle/>{storeError}</div>}{page==='Resumen'&&<Dashboard go={setPage} profile={profile} catalog={catalog}/>} {page==='Centro de control'&&<ControlHub profile={profile} refreshStore={refresh}/>} {corporateView(page)&&<ControlHub profile={profile} refreshStore={refresh} view={corporateView(page)}/>} {page==='Punto de venta'&&<POS catalog={catalog} profile={profile} refresh={refresh}/>} {page==='Productos'&&<Products catalog={catalog} profile={profile} refresh={refresh}/>}
      {page==='Compras'&&<Purchases profile={profile} catalog={catalog} refreshProducts={refresh}/>} {page==='Clientes'&&<Customers profile={profile}/>} {page==='Caja'&&<Cash profile={profile}/>} {page==='Estado de resultados'&&<IncomeStatementPage profile={profile}/>} {page==='Reportes'&&<Reports profile={profile}/>} {(page as string)==='Asistencia'&&profile&&<ControlHub profile={profile} refreshStore={refresh} view="attendance"/>} {page==='Configuración'&&<SettingsPage profile={profile} refreshStore={refresh}/>}
    </div></main>
  </div>
}

type PlatformSection='dashboard'|'businesses'
const industryLabels:Record<string,string>={retail:'Comercio general',minimarket:'Minimarket',pharmacy:'Farmacia',hardware:'Ferretería',clothing:'Ropa y calzado',restaurant:'Restaurante',services:'Servicios',other:'Otro'}
const planLabels:Record<string,string>={starter:'Inicial',business:'Negocios',enterprise:'Empresarial'}
const statusLabels:Record<string,string>={pending:'Pendiente',active:'Activa',suspended:'Suspendida',cancelled:'Cancelada'}

function PlatformAdminPortal({enterBusiness}:{enterBusiness:()=>void}){
  const [section,setSection]=useState<PlatformSection>('dashboard');const [summary,setSummary]=useState<PlatformSummary|null>(null);const [rows,setRows]=useState<PlatformBusiness[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [open,setOpen]=useState(false);const [q,setQ]=useState('')
  const refresh=async()=>{setLoading(true);setError('');try{const [s,b]=await Promise.all([loadPlatformSummary(),loadPlatformBusinesses()]);setSummary(s);setRows(b)}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar la plataforma')}finally{setLoading(false)}}
  useEffect(()=>{refresh()},[])
  const shown=rows.filter(b=>(b.name+' '+b.legalName+' '+industryLabels[b.industry]).toLowerCase().includes(q.toLowerCase()))
  return <div className="platform-shell"><aside className="platform-sidebar"><div className="platform-brand"><div className="brand-mark"><Globe2/></div><div><b>Grupo Multimarkets</b><span>PLATAFORMA SaaS</span></div></div><div className="platform-owner"><ShieldCheck/><div><small>Acceso propietario</small><b>Administrador general</b></div></div><nav><button className={section==='dashboard'?'active':''} onClick={()=>setSection('dashboard')}><LayoutDashboard/>Vista general</button><button className={section==='businesses'?'active':''} onClick={()=>setSection('businesses')}><Building2/>Empresas <em>{summary?.businesses??0}</em></button></nav><div className="platform-side-bottom"><button onClick={enterBusiness}><Store/>Entrar a MUNDO MEGA</button><button onClick={()=>supabase?.auth.signOut()}><LogOut/>Cerrar sesión</button></div></aside><main className="platform-main"><header className="platform-top"><div><span>CENTRO DE ADMINISTRACIÓN</span><h1>{section==='dashboard'?'Panel multiempresa':'Empresas y clientes'}</h1></div><div><button className="secondary" onClick={refresh}><RefreshCw className={loading?'spin':''}/>Actualizar</button><button className="primary" onClick={()=>setOpen(true)}><Plus/>Nueva empresa</button></div></header><div className="platform-content">{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}{section==='dashboard'?<PlatformDashboard summary={summary} rows={rows} loading={loading} goCompanies={()=>setSection('businesses')}/>:<PlatformBusinesses rows={shown} q={q} setQ={setQ} loading={loading} refresh={refresh}/>}</div></main>{open&&<NewBusinessDialog close={()=>setOpen(false)} saved={async()=>{setOpen(false);await refresh();setSection('businesses')}}/>}</div>
}

function PlatformDashboard({summary,rows,loading,goCompanies}:{summary:PlatformSummary|null;rows:PlatformBusiness[];loading:boolean;goCompanies:()=>void}){
  const industries=rows.reduce<Record<string,number>>((a,b)=>({...a,[b.industry]:(a[b.industry]??0)+1}),{})
  return <><div className="platform-welcome"><div><span>CONTROL TOTAL, DATOS SEPARADOS</span><h2>Tu red de empresas en un solo lugar</h2><p>Cada cliente trabaja en un espacio privado con sus propias ventas, usuarios, sucursales e inventario.</p></div><div className="privacy-seal"><ShieldCheck/><div><b>Aislamiento activo</b><small>Protegido por Supabase RLS</small></div></div></div><div className="platform-metrics"><PlatformMetric label="Empresas" value={summary?.businesses??0} note={`${summary?.activeBusinesses??0} activas`} icon={Building2}/><PlatformMetric label="Sucursales" value={summary?.branches??0} note="En toda la plataforma" icon={Store}/><PlatformMetric label="Usuarios" value={summary?.users??0} note="Cuentas activas" icon={Users}/><PlatformMetric label="Ventas de hoy" value={money(summary?.salesToday??0)} note="Total de la red" icon={CircleDollarSign}/></div><div className="platform-grid"><section className="card platform-companies-card"><CardHead title="Empresas recientes" sub="Estado de incorporación de tus clientes" action={<button className="link-btn" onClick={goCompanies}>Ver todas <ArrowUpRight/></button>}/>{loading?<div className="empty-table"><RefreshCw className="spin"/>Cargando empresas…</div>:rows.slice(0,6).map(b=><div className="platform-company-row" key={b.id}><div className="company-logo" style={{background:b.primaryColor}}>{b.name.slice(0,2).toUpperCase()}</div><div><b>{b.name}</b><span>{industryLabels[b.industry]} · {b.branches} sucursal{b.branches===1?'':'es'}</span></div><span className={`tenant-status ${b.status}`}>{statusLabels[b.status]}</span><strong>{planLabels[b.plan]}</strong></div>)}</section><section className="card platform-niches"><CardHead title="Empresas por nicho" sub="Distribución actual"/>{Object.entries(industries).length===0?<div className="empty-table"><Building2/>Aún no hay empresas</div>:Object.entries(industries).sort((a,b)=>b[1]-a[1]).map(([key,value])=><div className="niche-row" key={key}><span>{industryLabels[key]}</span><div><i style={{width:`${Math.max(12,value/rows.length*100)}%`}}/></div><b>{value}</b></div>)}</section></div></>
}
function PlatformMetric({label,value,note,icon:Icon}:{label:string;value:string|number;note:string;icon:any}){return <div className="card platform-metric"><div><span>{label}</span><strong>{value}</strong><small>{note}</small></div><div><Icon/></div></div>}

function PlatformBusinesses({rows,q,setQ,loading,refresh}:{rows:PlatformBusiness[];q:string;setQ:(v:string)=>void;loading:boolean;refresh:()=>Promise<void>}){
  const [busy,setBusy]=useState('');const [error,setError]=useState('');const [editing,setEditing]=useState<PlatformBusiness|null>(null)
  const change=async(b:PlatformBusiness,status:string)=>{const action=status==='suspended'?'suspender':status==='active'?'activar':'actualizar';if(!confirm(`Deseas ${action} ${b.name}?`))return;setBusy(b.id);setError('');try{await updatePlatformBusiness(b.id,{status});await refresh()}catch(e){setError(readError(e,'No fue posible actualizar'))}finally{setBusy('')}}
  const remove=async(b:PlatformBusiness)=>{if(!confirm(`Eliminar ${b.name}? Se bloqueara el acceso y dejara de aparecer en el panel. Los datos historicos se conservan.`))return;setBusy(b.id);setError('');try{await deletePlatformBusiness(b.id);await refresh()}catch(e){setError(readError(e,'No fue posible eliminar la empresa'))}finally{setBusy('')}}
  const invite=async(b:PlatformBusiness)=>{const email=prompt('Correo del administrador de esta empresa:');if(!email)return;const name=prompt('Nombre del administrador (opcional):')??'';setBusy(b.id);setError('');try{const result=await resendPlatformInvitation(b.id,email,name);await refresh();alert(result.mode==='password'?`Ya existia una cuenta para ${email}. Envie un enlace para definir o recuperar contrasena.`:`Invitacion enviada a ${email}. Debe abrir el correo y crear su contrasena.`)}catch(e){setError(readError(e,'No fue posible preparar la invitacion'))}finally{setBusy('')}}
  return <><div className="tenant-tools"><div className="search-box"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar empresa, razon social o nicho..."/></div><div className="tenant-legend"><span><i className="active"/>Activa</span><span><i className="pending"/>Pendiente</span><span><i className="suspended"/>Suspendida</span></div></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<section className="card tenant-table">{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Cargando empresas...</b></div>:<div className="table-scroll"><table><thead><tr><th>Empresa</th><th>Nicho</th><th>Plan</th><th>Uso</th><th>Ventas historicas</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{rows.map(b=><tr key={b.id}><td><div className="tenant-name"><span style={{background:b.primaryColor}}>{b.name.slice(0,2).toUpperCase()}</span><div><b>{b.name}</b><small>{b.legalName||b.slug}</small></div></div></td><td><span className="industry-chip">{industryLabels[b.industry]}</span></td><td><b>{planLabels[b.plan]}</b><small className="subline">{b.maxUsers} usuarios ? {b.maxBranches} sucursales</small></td><td><b>{b.users}/{b.maxUsers} usuarios</b><small className="subline">{b.branches}/{b.maxBranches} sucursales ? {b.products} productos</small></td><td><b>{money(b.salesTotal)}</b></td><td><span className={`tenant-status ${b.status}`}>{statusLabels[b.status]}</span></td><td><div className="tenant-actions"><button title="Editar empresa" disabled={busy===b.id} onClick={()=>setEditing(b)}><Pencil/></button>{b.status==='pending'&&<button title="Enviar invitacion" disabled={busy===b.id} onClick={()=>invite(b)}><Mail/></button>}{b.status==='active'?<button className="danger" title="Suspender" disabled={busy===b.id} onClick={()=>change(b,'suspended')}><Power/></button>:b.status==='suspended'?<button className="success" title="Reactivar" disabled={busy===b.id} onClick={()=>change(b,'active')}><CheckCircle2/></button>:null}<button className="danger" title="Eliminar empresa" disabled={busy===b.id} onClick={()=>remove(b)}><Trash2/></button></div></td></tr>)}</tbody></table>{rows.length===0&&<div className="empty-table"><Building2/><b>No se encontraron empresas</b></div>}</div>}</section>{editing&&<EditBusinessDialog business={editing} close={()=>setEditing(null)} saved={async()=>{setEditing(null);await refresh()}}/>}</>
}
function NewBusinessDialog({close,saved}:{close:()=>void;saved:()=>Promise<void>}){
 const [form,setForm]=useState({name:'',legalName:'',industry:'retail',adminEmail:'',adminName:'',plan:'starter',slogan:'',primaryColor:'#155b3d',accentColor:'#c9f45c',attendanceMode:'legacy'});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const set=(k:string,v:string)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{const result=await createPlatformBusiness({...form,attendanceMode:form.attendanceMode as 'legacy'|'employee_qr_v2'});await saved();alert(result.emailResult.mode==='password'?`Empresa creada. ${form.adminEmail} ya tenia cuenta, envi? enlace para definir o recuperar contrasena.`:`Empresa creada e invitacion enviada a ${form.adminEmail}.`)}catch(err){setError(readError(err,'No fue posible crear la empresa'))}finally{setBusy(false)}}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="product-dialog tenant-dialog card" onSubmit={submit}><div className="dialog-head"><div><span className="eyebrow">NUEVO CLIENTE</span><h3>Crear empresa independiente</h3><p>Se creará con datos, inventario, usuarios y sucursales privados.</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid"><label>Nombre comercial<input required value={form.name} onChange={e=>set('name',e.target.value)} placeholder="Ej. Farmacia Central"/></label><label>Razón social<input value={form.legalName} onChange={e=>set('legalName',e.target.value)} placeholder="Ej. Farmacia Central, S.A."/></label><label>Nicho<select value={form.industry} onChange={e=>set('industry',e.target.value)}>{Object.entries(industryLabels).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label><label>Plan<select value={form.plan} onChange={e=>set('plan',e.target.value)}><option value="starter">Inicial · 1 sucursal / 5 usuarios</option><option value="business">Negocios · 5 sucursales / 30 usuarios</option><option value="enterprise">Empresarial · hasta 100 sucursales</option></select></label><label>Modo de asistencia<select value={form.attendanceMode} onChange={e=>set('attendanceMode',e.target.value)}><option value="legacy">Legacy por kiosco</option><option value="employee_qr_v2">QR V2 por empleado</option></select></label><label>Administrador principal<input required value={form.adminName} onChange={e=>set('adminName',e.target.value)} placeholder="Nombre completo"/></label><label>Correo para activar la cuenta<input required type="email" value={form.adminEmail} onChange={e=>set('adminEmail',e.target.value)} placeholder="administrador@empresa.com"/></label><label className="full">Eslogan<input value={form.slogan} onChange={e=>set('slogan',e.target.value)} placeholder="Una frase para la empresa"/></label><label>Color principal<div className="color-field"><input type="color" value={form.primaryColor} onChange={e=>set('primaryColor',e.target.value)}/><input value={form.primaryColor} onChange={e=>set('primaryColor',e.target.value)}/></div></label><label>Color de acento<div className="color-field"><input type="color" value={form.accentColor} onChange={e=>set('accentColor',e.target.value)}/><input value={form.accentColor} onChange={e=>set('accentColor',e.target.value)}/></div></label></div><div className="tenant-security-note"><ShieldCheck/><span><b>Privacidad por diseño</b>Esta empresa no podrá ver información de MUNDO MEGA ni de otros clientes.</span></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Creando espacio privado…':'Crear empresa'}</button></div></form></div>
}

function EditBusinessDialog({business,close,saved}:{business:PlatformBusiness;close:()=>void;saved:()=>Promise<void>}){
 const [form,setForm]=useState({name:business.name,legalName:business.legalName,industry:business.industry,plan:business.plan,status:business.status,slogan:business.slogan,primaryColor:business.primaryColor,accentColor:business.accentColor});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const set=(k:string,v:string)=>setForm(f=>({...f,[k]:v}));const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{await updatePlatformBusiness(business.id,form);await saved()}catch(err){setError(readError(err,'No fue posible actualizar la empresa'))}finally{setBusy(false)}}
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><form className="product-dialog tenant-dialog card" onSubmit={submit}><div className="dialog-head"><div><span className="eyebrow">EDITAR EMPRESA</span><h3>{business.name}</h3><p>Actualiza datos comerciales, plan, estado e identidad visual.</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid"><label>Nombre comercial<input required value={form.name} onChange={e=>set('name',e.target.value)}/></label><label>Razon social<input value={form.legalName} onChange={e=>set('legalName',e.target.value)}/></label><label>Nicho<select value={form.industry} onChange={e=>set('industry',e.target.value)}>{Object.entries(industryLabels).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label><label>Plan<select value={form.plan} onChange={e=>set('plan',e.target.value)}><option value="starter">Inicial - 1 sucursal / 5 usuarios</option><option value="business">Negocios - 5 sucursales / 30 usuarios</option><option value="enterprise">Empresarial - hasta 100 sucursales</option></select></label><label>Estado<select value={form.status} onChange={e=>set('status',e.target.value)}><option value="pending">Pendiente</option><option value="active">Activa</option><option value="suspended">Suspendida</option></select></label><label>Eslogan<input value={form.slogan} onChange={e=>set('slogan',e.target.value)}/></label><label>Color principal<div className="color-field"><input type="color" value={form.primaryColor} onChange={e=>set('primaryColor',e.target.value)}/><input value={form.primaryColor} onChange={e=>set('primaryColor',e.target.value)}/></div></label><label>Color de acento<div className="color-field"><input type="color" value={form.accentColor} onChange={e=>set('accentColor',e.target.value)}/><input value={form.accentColor} onChange={e=>set('accentColor',e.target.value)}/></div></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando...':'Guardar cambios'}</button></div></form></div>
}
function AuthScreen(){
  const [mode,setMode]=useState<'login'|'signup'>('login'); const [email,setEmail]=useState(''); const [password,setPassword]=useState(''); const [name,setName]=useState(''); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const [notice,setNotice]=useState('')
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');setNotice('');try{
    if(!supabase)throw new Error('Supabase no esta configurado')
    if(mode==='login'){const credential=email.trim();const loginEmail=credential.includes('@')?credential:await resolveLoginUsername(credential);const {error}=await supabase.auth.signInWithPassword({email:loginEmail,password});if(error)throw error}
    else{const {data,error}=await supabase.auth.signUp({email,password,options:{emailRedirectTo:window.location.origin,data:{full_name:name}}});if(error)throw error;if(!data.session)setNotice('Cuenta activada. Revisa tu correo para confirmar el acceso.');}
  }catch(err){setError(err instanceof Error?translateAuthError(err.message):'No fue posible continuar')}finally{setBusy(false)}}
  const resend=async()=>{if(!supabase||!email){setError('Escribe primero tu correo electronico.');return}setBusy(true);setError('');const {error}=await supabase.auth.resend({type:'signup',email,options:{emailRedirectTo:window.location.origin}});setBusy(false);if(error)setError(translateAuthError(error.message));else setNotice('Te enviamos un nuevo enlace. Usa el correo mas reciente.')}
  return <main className="auth-page"><section className="auth-showcase"><div className="auth-brand"><div className="brand-mark"><Store/></div><b>Grupo Multimarkets S.A.</b></div><div className="auth-copy"><span>PLATAFORMA MULTIEMPRESA</span><h1>Vende.<br/>Crece.</h1><p className="brand-slogan">Cada empresa, su propio espacio.</p><div className="auth-benefits"><div><CheckCircle2/><span><b>Datos independientes</b><small>Ventas, inventario y clientes privados.</small></span></div><div><CheckCircle2/><span><b>Para diferentes nichos</b><small>Comercios, farmacias, ferreterias y mas.</small></span></div><div><CheckCircle2/><span><b>Administracion central</b><small>Control general sin mezclar operaciones.</small></span></div></div></div><div className="auth-quote">GRUPO MULTIMARKETS - Plataforma empresarial.</div></section><section className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><div className="auth-mobile-brand"><div className="brand-mark"><Store/></div><b>Grupo Multimarkets S.A.</b></div><span className="eyebrow">BIENVENIDO</span><h2>{mode==='login'?'Inicia sesion':'Activa tu cuenta'}</h2><p>{mode==='login'?'Ingresa con correo o usuario.':'Usa exactamente el correo que recibio la invitacion.'}</p>{mode==='signup'&&<label>Tu nombre<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Ej. Ana Lopez"/></label>}<label>{mode==='login'?'Correo o usuario':'Correo electronico'}<input required type={mode==='login'?'text':'email'} value={email} onChange={e=>setEmail(e.target.value)} placeholder={mode==='login'?'usuario o nombre@empresa.com':'nombre@empresa.com'}/></label><label>Contrasena<input required type="password" minLength={8} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Minimo 8 caracteres"/></label>{error&&<div className="auth-message error">{error}</div>}{notice&&<div className="auth-message notice">{notice}</div>}<button className="auth-submit" disabled={busy}>{busy?<><RefreshCw className="spin"/>Procesando...</>:mode==='login'?'Iniciar sesion':'Activar cuenta invitada'}</button><div className="auth-switch">{mode==='login'?'Recibiste una invitacion?':'Ya activaste tu cuenta?'} <button type="button" onClick={()=>{setMode(mode==='login'?'signup':'login');setError('');setNotice('')}}>{mode==='login'?'Activar cuenta':'Iniciar sesion'}</button></div></form></section></main>
}


function PasswordSetup({done,clearForce=false}:{done:()=>void;clearForce?:boolean}){
  const [password,setPassword]=useState('');const [confirm,setConfirm]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('')
  const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');if(password.length<8){setError('La contrasena debe tener al menos 8 caracteres.');return}if(password!==confirm){setError('Las contrasenas no coinciden.');return}setBusy(true);try{if(!supabase)throw new Error('Supabase no esta configurado');const {error}=await supabase.auth.updateUser({password});if(error)throw error;if(clearForce)await completeForcePasswordChange();done()}catch(err){setError(err instanceof Error?translateAuthError(err.message):'No fue posible guardar la contrasena')}finally{setBusy(false)}}
  return <main className="auth-page"><section className="auth-showcase"><div className="auth-brand"><div className="brand-mark"><Store/></div><b>Grupo Multimarkets S.A.</b></div><div className="auth-copy"><span>INVITACION ACEPTADA</span><h1>Define tu<br/>contrasena.</h1><p className="brand-slogan">Tu espacio privado ya est? casi listo.</p></div><div className="auth-quote">MUNDO MEGA ? Acceso seguro.</div></section><section className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><span className="eyebrow">ULTIMO PASO</span><h2>Crea tu contrasena</h2><p>La usar?s para entrar al sistema desde ahora.</p><label>Nueva contrasena<input required type="password" minLength={8} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Minimo 8 caracteres"/></label><label>Confirmar contrasena<input required type="password" minLength={8} value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="Repite la contrasena"/></label>{error&&<div className="auth-message error">{error}</div>}<button className="auth-submit" disabled={busy}>{busy?<><RefreshCw className="spin"/>Guardando...</>:'Guardar y entrar'}</button></form></section></main>
}
function translateAuthError(message:string){if(message.includes('Invalid login'))return 'Correo o contraseña incorrectos.';if(message.includes('already registered'))return 'Este correo ya está registrado.';if(message.includes('Password'))return 'La contraseña debe tener al menos 8 caracteres.';return message}
function readError(error:unknown,fallback:string){if(error instanceof Error)return error.message;if(error&&typeof error==='object'&&'message' in error)return String((error as {message?:unknown}).message||fallback);return fallback}

function BranchSwitcher({profile,refresh}:{profile:StoreProfile|null;refresh:()=>Promise<void>}){const [open,setOpen]=useState(false);const [rows,setRows]=useState<Branch[]>([]);const toggle=async()=>{if(!profile||!['admin','supervisor'].includes(profile.role))return;const next=!open;setOpen(next);if(next)setRows((await loadBranches(profile)).filter(b=>b.active))};const choose=async(id:string)=>{await switchBranch(id);await refresh();setOpen(false)};return <div className="branch-switch-wrap"><button className="branch" onClick={toggle}><span className="branch-icon">{profile?.businessName?.[0]??'M'}</span><div><small>{profile?.branchName??'Sucursal actual'}</small><strong>{profile?.businessName??'Cargando negocio…'}</strong></div>{['admin','supervisor'].includes(profile?.role??'')&&<ChevronDown size={16}/>}</button>{open&&<div className="branch-menu"><span>Cambiar de sucursal</span>{rows.map(b=><button className={b.id===profile?.branchId?'active':''} key={b.id} onClick={()=>choose(b.id)}><Store/><div><b>{b.name}</b><small>{b.address||'Sin dirección'}</small></div>{b.id===profile?.branchId&&<CheckCircle2/>}</button>)}</div>}</div>}

function Topbar({title,openMenu}:{title:string,openMenu:()=>void}){return <header className="topbar"><button className="menu-btn" onClick={openMenu}><Menu/></button><div><h1>{title}</h1><p>{title==='Resumen'?'MUNDO MEGA · Minimarket más cercano':'Grupo Multimarkets S.A.'}</p></div><div className="top-actions"><div className="search-global"><Search size={18}/><input placeholder="Buscar en el sistema..."/><kbd>⌘ K</kbd></div><button className="icon-btn notification"><Bell size={20}/><i/></button><div className="status-dot"><span/>Caja abierta</div></div></header>}

const chartData=[{h:'7am',v:180},{h:'8am',v:260},{h:'9am',v:410},{h:'10am',v:690},{h:'11am',v:520},{h:'12pm',v:840},{h:'1pm',v:650},{h:'2pm',v:1020},{h:'3pm',v:880},{h:'4pm',v:1240},{h:'5pm',v:1150},{h:'6pm',v:1480}]
function Dashboard({go,profile,catalog}:{go:(p:Page)=>void;profile:StoreProfile|null;catalog:Product[]}){const [liveSales,setLiveSales]=useState<LiveSale[]>([]);const refreshSales=async()=>{if(profile)setLiveSales(await loadSales(profile))};useEffect(()=>{refreshSales()},[profile]);const today=liveSales.filter(s=>new Date(s.date).toDateString()===new Date().toDateString()&&s.status==='completed');const revenue=today.reduce((s,x)=>s+x.total,0);const profit=today.reduce((s,x)=>s+x.total-x.cost,0);const hourly=Array.from({length:12},(_,i)=>{const hour=i+7;return {h:`${hour>12?hour-12:hour}${hour>=12?'pm':'am'}`,v:today.filter(s=>new Date(s.date).getHours()===hour).reduce((n,s)=>n+s.total,0)}});return <>
  <div className="welcome"><div><h2>Buenos días, Ana <span>👋</span></h2><p>Todo marcha bien. Aquí tienes el pulso de tu negocio.</p></div><button className="primary" onClick={()=>go('Punto de venta')}><ShoppingCart size={18}/>Nueva venta</button></div>
  <div className="metric-grid"><Metric label="Ventas de hoy" value={money(revenue)} change="Datos reales" up icon={CircleDollarSign}/><Metric label="Transacciones" value={String(today.length)} change="Completadas" up icon={ReceiptText}/><Metric label="Ticket promedio" value={money(today.length?revenue/today.length:0)} change="Promedio" up icon={ShoppingBag}/><Metric label="Ganancia estimada" value={money(profit)} change="Venta − costo" up={profit>=0} icon={BarChart3}/></div>
  <div className="dashboard-grid"><section className="card sales-chart"><CardHead title="Ventas de hoy" sub="Ingresos por hora" action={<button className="select-small">Hoy <ChevronDown size={14}/></button>}/><div className="chart-total"><strong>Q 4,286.50</strong><span><ArrowUpRight size={15}/>12.5% vs. ayer</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={chartData}><defs><linearGradient id="salesFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#39a96b" stopOpacity={.28}/><stop offset="100%" stopColor="#39a96b" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#eceeea"/><XAxis dataKey="h" axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#849087'}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:11,fill:'#849087'}} tickFormatter={v=>`Q${v}`}/><Tooltip formatter={(v)=>money(Number(v))}/><Area type="monotone" dataKey="v" stroke="#278d57" strokeWidth={3} fill="url(#salesFill)"/></AreaChart></ResponsiveContainer></div></section>
    <section className="card low-stock"><CardHead title="Stock por agotarse" sub="Requieren atención" action={<button className="link-btn" onClick={()=>go('Productos')}>Ver inventario</button>}/>{catalog.filter(p=>p.stock<=p.minStock).length===0?<div className="empty-compact"><CheckCircle2/>Inventario saludable</div>:catalog.filter(p=>p.stock<=p.minStock).slice(0,4).map(p=><div className="stock-row" key={p.id}><ProductThumb p={p}/><div className="stock-info"><strong>{p.name}</strong><span>{p.sku} · {p.unit}</span><div className="progress"><i style={{width:`${Math.min(100,p.stock/Math.max(1,p.minStock)*100)}%`}}/></div></div><div className="stock-count"><b>{p.stock}</b><span>en stock</span></div></div>)}</section>
  </div>
  <section className="card recent"><CardHead title="Ventas recientes" sub="Últimas transacciones del día" action={<button className="link-btn">Ver todas <ArrowUpRight size={15}/></button>}/><SalesTable live={liveSales.slice(0,8)} profile={profile} onChanged={refreshSales}/></section>
  </>}
function Metric({label,value,change,up,icon:Icon}:{label:string,value:string,change:string,up:boolean,icon:any}){return <div className="metric card"><div className="metric-top"><span>{label}</span><div className="metric-icon"><Icon size={20}/></div></div><strong>{value}</strong><p className={up?'positive':'negative'}>{up?<ArrowUpRight/>:<ArrowDownRight/>}{change}<span> vs. ayer</span></p></div>}
function CardHead({title,sub,action}:{title:string,sub?:string,action?:any}){return <div className="card-head"><div><h3>{title}</h3>{sub&&<p>{sub}</p>}</div>{action}</div>}

function ControlHub({profile,refreshStore,view}:{profile:StoreProfile|null;refreshStore:()=>Promise<void>;view?:CorporateView}){
  const [internalSection,setInternalSection]=useState<CorporateView>('overview');const section=view??internalSection
  if(!profile)return null
  const items:{id:CorporateView;label:string;Icon:any}[]=[
    {id:'overview',label:'Vista general',Icon:LayoutDashboard},{id:'movements',label:'Movimientos',Icon:RefreshCw},{id:'cashClosures',label:'Cierres de caja',Icon:ReceiptText},{id:'inventory',label:'Inventario global',Icon:Boxes},{id:'attendance',label:'Asistencia',Icon:CalendarDays},
    ...(profile.role==='admin'?[{id:'cashControl' as const,label:'Control de caja corporativo',Icon:WalletCards},{id:'branches' as const,label:'Sucursales',Icon:Store},{id:'team' as const,label:'Usuarios',Icon:Users}]:[])
  ]
  return <div className="control-hub"><div className="hub-header"><div><span>CENTRO CORPORATIVO</span><h2>{profile.businessName}</h2><p>Administración y supervisión de todas las tiendas.</p></div><div className="hub-user"><div className="avatar">{profile.fullName.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}</div><div><b>{profile.fullName}</b><small>{profile.role==='admin'?'Administrador central':'Supervisor corporativo'}</small></div></div></div>{!view&&<nav className="hub-nav">{items.map(({id,label,Icon})=><button className={section===id?'active':''} key={id} onClick={()=>setInternalSection(id)}><Icon/>{label}</button>)}</nav>}<div className="hub-content">{section==='overview'&&<ControlCenter profile={profile}/>} {section==='movements'&&<ControlMovements profile={profile}/>} {section==='cashClosures'&&<CashClosureReports profile={profile}/>} {section==='cashControl'&&profile.role==='admin'&&<CorporateCashControl profile={profile}/>} {section==='inventory'&&<ControlInventoryMatrix/>} {section==='attendance'&&<AttendanceControl profile={profile}/>} {section==='branches'&&profile.role==='admin'&&<BranchSettings profile={profile} refreshStore={refreshStore}/>} {section==='team'&&profile.role==='admin'&&<TeamSettings profile={profile}/>}</div></div>
}

const attendanceKindLabel=(kind:string)=>({start_shift:'Inicio de jornada',lunch_out:'Ir a comer',lunch_in:'Regresando de comer',end_shift:'Terminar dia',custom:'Personalizada'}[kind]??kind)
async function saveAttendanceEmployee(id:string,changes:{fullName?:string;position?:string;baseSalary?:number;branchId?:string|null;active?:boolean}){if(!supabase)throw new Error('Supabase no está configurado');const payload:any={};if(changes.fullName!==undefined)payload.full_name=changes.fullName;if(changes.position!==undefined)payload.position=changes.position||null;if(changes.baseSalary!==undefined)payload.base_salary=changes.baseSalary;if(changes.branchId!==undefined)payload.branch_id=changes.branchId||null;if(changes.active!==undefined)payload.active=changes.active;const {error}=await supabase.from('attendance_employees').update(payload).eq('id',id);if(error)throw error}
async function deleteAttendanceEmployee(id:string){if(!supabase)throw new Error('Supabase no está configurado');const {error}=await supabase.from('attendance_employees').delete().eq('id',id);if(error)throw error}
async function deleteAttendanceEvent(id:string){if(!supabase)throw new Error('Supabase no está configurado');const {error}=await supabase.from('attendance_events').delete().eq('id',id);if(error)throw error}
async function deleteAttendanceCategory(id:string){if(!supabase)throw new Error('Supabase no está configurado');const events=await supabase.from('attendance_events').delete().eq('category_id',id);if(events.error)throw events.error;const category=await supabase.from('attendance_categories').delete().eq('id',id);if(category.error)throw category.error}
async function saveAttendanceCategory(id:string,changes:{name?:string;kind?:string;active?:boolean}){if(!supabase)throw new Error('Supabase no está configurado');const payload:any={};if(changes.name!==undefined)payload.name=changes.name;if(changes.kind!==undefined)payload.kind=changes.kind;if(changes.active!==undefined)payload.active=changes.active;const {error}=await supabase.from('attendance_categories').update(payload).eq('id',id);if(error)throw error}

function AttendanceControl({profile}:{profile:StoreProfile}){const [employees,setEmployees]=useState<AttendanceEmployee[]>([]);const [categories,setCategories]=useState<AttendanceCategory[]>([]);const [events,setEvents]=useState<AttendanceEvent[]>([]);const [branches,setBranches]=useState<Branch[]>([]);const [period,setPeriod]=useState<'first'|'second'|'month'>(defaultAttendancePeriod());const [workRule,setWorkRule]=useState<'withSunday'|'withoutSunday'>('withoutSunday');const [branch,setBranch]=useState(profile.branchId);const [qrBranch,setQrBranch]=useState(profile.branchId);const [tab,setTab]=useState<'qr'|'v2'|'employees'|'attendance'|'payroll'>('attendance');const [token,setToken]=useState('');const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [employeeOpen,setEmployeeOpen]=useState(false);const [categoryOpen,setCategoryOpen]=useState(false);const [editingEmployee,setEditingEmployee]=useState<AttendanceEmployee|null>(null);const [editingCategory,setEditingCategory]=useState<AttendanceCategory|null>(null);const range=useMemo(()=>attendanceRange(period),[period]);const refresh=async()=>{setLoading(true);setError('');try{const [data,k,b]=await Promise.all([loadAttendanceAdmin(profile,range.from,range.to),ensureAttendanceKiosk(qrBranch),loadBranches(profile)]);setEmployees(data.employees);setCategories(data.categories);setEvents(data.events);setToken(k);setBranches(b)}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar asistencia')}finally{setLoading(false)}};useEffect(()=>{refresh()},[period,qrBranch]);const link=token?`${window.location.origin}/?attendance=${token}`:'';const visibleEmployees=employees.filter(e=>e.active&&(!branch||e.branchId===branch));const visibleEvents=events.filter(e=>!branch||e.branchName===(branches.find(b=>b.id===branch)?.name??e.branchName));const payroll=visibleEmployees.map(e=>attendancePayroll(e,visibleEvents.filter(ev=>ev.employeeId===e.id),range,workRule));const totals=payroll.reduce((a,r)=>({earned:a.earned+r.earned,days:a.days+r.presentDays}),{earned:0,days:0});const removeEmployee=async(e:AttendanceEmployee)=>{if(!window.confirm(`¿Eliminar permanentemente a ${e.fullName}? También se borrarán sus marcajes de asistencia y no se podrá recuperar.`))return;await deleteAttendanceEmployee(e.id);await refresh()};const removeCategory=async(c:AttendanceCategory)=>{if(!window.confirm(`¿Eliminar permanentemente la categoría "${c.name}"? También se borrarán los marcajes registrados con esta categoría y no se podrá recuperar.`))return;await deleteAttendanceCategory(c.id);await refresh()};const removeEvent=async(e:AttendanceEvent)=>{if(!window.confirm(`�Eliminar este registro de asistencia de ${e.employeeName}? No se podr� recuperar.`))return;await deleteAttendanceEvent(e.id);await refresh()};return <><div className="hub-section-head"><div><h3>Asistencia y salarios</h3><p>QR compartido por sucursal, medio turno y salarios con regla de domingos.</p></div><div className="control-actions"><button className="secondary" onClick={()=>printAttendanceReport(profile,visibleEvents,visibleEmployees,range)}><Download/>Imprimir asistencia</button><button className="primary" onClick={()=>printPayrollReport(profile,payroll,range,workRule)}><ReceiptText/>Imprimir salarios</button></div></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<div className="inventory-control-stats"><MiniStat label="Empleados" value={String(visibleEmployees.length)} icon={Users}/><MiniStat label="Marcajes" value={String(visibleEvents.length)} icon={CalendarDays}/><MiniStat label="Dias pagables" value={String(totals.days)} icon={CheckCircle2}/><MiniStat label="Salarios calculados" value={money(totals.earned)} icon={CircleDollarSign}/></div><div className="movement-filters card"><select value={period} onChange={e=>setPeriod(e.target.value as any)}><option value="first">Primera quincena</option><option value="second">Segunda quincena</option><option value="month">Mes completo</option></select><select value={workRule} onChange={e=>setWorkRule(e.target.value as any)}><option value="withoutSunday">No trabaja domingos</option><option value="withSunday">Incluye domingos</option></select><select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><button className="secondary" onClick={refresh}><RefreshCw className={loading?'spin':''}/>Actualizar</button></div><div className="hub-nav"><button className={tab==='qr'?'active':''} onClick={()=>setTab('qr')}><CalendarDays/>QR</button><button className={tab==='v2'?'active':''} onClick={()=>setTab('v2')}><ScanBarcode/>QR V2</button><button className={tab==='employees'?'active':''} onClick={()=>setTab('employees')}><Users/>Empleados</button><button className={tab==='attendance'?'active':''} onClick={()=>setTab('attendance')}><Eye/>Asistencia</button><button className={tab==='payroll'?'active':''} onClick={()=>setTab('payroll')}><CircleDollarSign/>Salarios</button></div>{tab==='qr'&&<section className="card attendance-kiosk-card"><div><h3>QR general por sucursal</h3><p>Un solo QR para todos los empleados de la sucursal seleccionada. No es un QR por empleado.</p><select value={qrBranch} onChange={e=>setQrBranch(e.target.value)}>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><input readOnly value={link}/><div className="dialog-actions"><button className="secondary" onClick={()=>navigator.clipboard?.writeText(link)}>Copiar link</button><button className="primary" onClick={()=>window.open(link,'_blank')}>Abrir marcador</button></div></div>{link&&<img alt="QR asistencia" src={`https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(link)}`}/>}</section>}{tab==='v2'&&<AttendanceQrV2Admin profile={profile} branches={branches}/>} {tab==='employees'&&<><section className="card movement-table"><CardHead title="Empleados de asistencia" sub="Imprime asistencia o salario individual desde aqui" action={<div><button className="secondary" onClick={()=>setCategoryOpen(true)}><Plus/>Categoria</button><button className="primary" onClick={()=>setEmployeeOpen(true)}><Plus/>Empleado</button></div>}/><div className="table-scroll"><table><thead><tr><th>Empleado</th><th>Puesto</th><th>Sucursal</th><th>Base quincenal</th><th>Estado</th><th>Imprimir</th><th>Acciones</th></tr></thead><tbody>{employees.map(e=>{const empEvents=events.filter(ev=>ev.employeeId===e.id);const empPayroll=attendancePayroll(e,empEvents,range,workRule);return <tr key={e.id}><td><b>{e.fullName}</b></td><td>{e.position||'Colaborador'}</td><td>{e.branchName}</td><td>{money(e.baseSalary)}</td><td><span className={e.active?'badge success':'badge neutral'}>{e.active?'Activo':'Inactivo'}</span></td><td><div className="tenant-actions"><button title="Imprimir asistencia" onClick={()=>printAttendanceReport(profile,empEvents,[e],range)}><CalendarDays/></button><button title="Imprimir salario" onClick={()=>printPayrollReport(profile,[empPayroll],range,workRule)}><ReceiptText/></button></div></td><td><div className="tenant-actions"><button title="Editar empleado" onClick={()=>setEditingEmployee(e)}><Pencil/></button><button title={e.active?'Eliminar empleado':'Activar empleado'} onClick={()=>e.active?removeEmployee(e):updateAttendanceEmployee(e.id,{active:true}).then(refresh)}>{e.active?<Trash2/>:<Power/>}</button></div></td></tr>})}</tbody></table></div></section><section className="card movement-table"><CardHead title="Categorías de entrada y salida" sub="Edita las opciones que el empleado verá al escanear el QR"/><div className="table-scroll"><table><thead><tr><th>Categoría</th><th>Tipo</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{categories.map(c=><tr key={c.id}><td><b>{c.name}</b></td><td>{attendanceKindLabel(c.kind)}</td><td><span className={c.active?'badge success':'badge neutral'}>{c.active?'Activa':'Inactiva'}</span></td><td><div className="tenant-actions"><button title="Editar categoría" onClick={()=>setEditingCategory(c)}><Pencil/></button><button title="Eliminar categoría permanentemente" onClick={()=>removeCategory(c)}><Trash2/></button></div></td></tr>)}</tbody></table></div></section></>}{tab==='attendance'&&<section className="card movement-table"><CardHead title="Reporte de asistencia" sub="Filtrado por periodo y sucursal"/><div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Empleado</th><th>Categoria</th><th>Sucursal</th><th>Nota</th><th>Acciones</th></tr></thead><tbody>{visibleEvents.slice(0,120).map(e=><tr key={e.id}><td>{new Date(e.markedAt).toLocaleString('es-GT')}</td><td><b>{e.employeeName}</b></td><td>{e.categoryName}</td><td>{e.branchName}</td><td>{e.note}</td><td><div className="tenant-actions"><button title="Eliminar registro" onClick={()=>removeEvent(e)}><Trash2/></button></div></td></tr>)}</tbody></table>{visibleEvents.length===0&&<div className="empty-table"><CalendarDays/><b>Sin marcajes en este periodo</b></div>}</div></section>}{tab==='payroll'&&<section className="card movement-table"><CardHead title="Control quincenal de salarios" sub={`${range.from.toLocaleDateString('es-GT')} al ${range.to.toLocaleDateString('es-GT')} - ${workRule==='withoutSunday'?'sin domingos':'con domingos'}`}/><div className="table-scroll"><table><thead><tr><th>Empleado</th><th>Puesto</th><th>Dias pagables</th><th>Base quincenal</th><th>Pago segun asistencia</th><th>Estado</th></tr></thead><tbody>{payroll.map(r=><tr key={r.employee.id}><td><b>{r.employee.fullName}</b><span className="subline">{r.employee.branchName}</span></td><td>{r.employee.position||'Colaborador'}</td><td>{r.presentDays}/{r.workingDays}</td><td>{money(r.baseSalary)}</td><td><b>{money(r.earned)}</b></td><td><span className={r.presentDays>=r.workingDays?'badge success':'badge warning'}>{r.presentDays>=r.workingDays?'Completo':'Parcial'}</span></td></tr>)}</tbody></table>{payroll.length===0&&<div className="empty-table"><Users/><b>Agrega empleados para calcular asistencia</b></div>}</div></section>}{employeeOpen&&<AttendanceEmployeeDialog profile={profile} branches={branches} close={()=>setEmployeeOpen(false)} saved={async()=>{setEmployeeOpen(false);await refresh()}}/>}{editingEmployee&&<AttendanceEmployeeDialog profile={profile} branches={branches} employee={editingEmployee} close={()=>setEditingEmployee(null)} saved={async()=>{setEditingEmployee(null);await refresh()}}/>}{categoryOpen&&<AttendanceCategoryDialog profile={profile} close={()=>setCategoryOpen(false)} saved={async()=>{setCategoryOpen(false);await refresh()}}/>}{editingCategory&&<AttendanceCategoryDialog profile={profile} category={editingCategory} close={()=>setEditingCategory(null)} saved={async()=>{setEditingCategory(null);await refresh()}}/>}</>}

function AttendanceEmployeeDialog({profile,branches,employee,close,saved}:{profile:StoreProfile;branches:Branch[];employee?:AttendanceEmployee;close:()=>void;saved:()=>Promise<void>}){const [form,setForm]=useState({fullName:employee?.fullName??'',position:employee?.position??'',baseSalary:String(employee?.baseSalary??750),branchId:employee?.branchId??profile.branchId});const [busy,setBusy]=useState(false);const [error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{if(employee){await saveAttendanceEmployee(employee.id,{fullName:form.fullName,position:form.position,baseSalary:Number(form.baseSalary),branchId:form.branchId})}else{await createAttendanceEmployee(profile,{...form,baseSalary:Number(form.baseSalary)})}await saved()}catch(err){setError(err instanceof Error?err.message:employee?'No fue posible editar empleado':'No fue posible crear empleado')}finally{setBusy(false)}};return <div className="modal-backdrop"><form className="product-dialog small-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>{employee?'Editar empleado':'Nuevo empleado'}</h3><p>{employee?'Actualiza nombre, puesto, sucursal o salario base.':'No necesita usuario del sistema para marcar asistencia.'}</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid one"><label>Nombre completo<input required value={form.fullName} onChange={e=>setForm({...form,fullName:e.target.value})}/></label><label>Puesto o categoria<input value={form.position} onChange={e=>setForm({...form,position:e.target.value})}/></label><label>Base quincenal (Q)<input required type="number" step="0.01" value={form.baseSalary} onChange={e=>setForm({...form,baseSalary:e.target.value})}/></label><label>Sucursal<select value={form.branchId??''} onChange={e=>setForm({...form,branchId:e.target.value})}>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando...':employee?'Guardar cambios':'Crear empleado'}</button></div></form></div>}

function AttendanceCategoryDialog({profile,category,close,saved}:{profile:StoreProfile;category?:AttendanceCategory;close:()=>void;saved:()=>Promise<void>}){const [name,setName]=useState(category?.name??'');const [kind,setKind]=useState<string>(category?.kind??'custom');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{if(category){await saveAttendanceCategory(category.id,{name,kind})}else{await createAttendanceCategory(profile,{name,kind})}await saved()}catch(err){setError(err instanceof Error?err.message:category?'No fue posible editar categoria':'No fue posible crear categoria')}finally{setBusy(false)}};return <div className="modal-backdrop"><form className="product-dialog small-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>{category?'Editar categoria':'Nueva categoria'}</h3><p>Ej. Inicio de turno nocturno, salida especial, permiso.</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid one"><label>Nombre<input required value={name} onChange={e=>setName(e.target.value)}/></label><label>Tipo<select value={kind} onChange={e=>setKind(e.target.value)}><option value="start_shift">Inicio de jornada</option><option value="lunch_out">Ir a comer</option><option value="lunch_in">Regresando de comer</option><option value="end_shift">Terminar dia</option><option value="custom">Personalizada</option></select></label></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={busy}>{busy?'Guardando...':category?'Guardar cambios':'Crear categoria'}</button></div></form></div>}

function AttendanceKiosk({token}:{token:string}){const [data,setData]=useState<any>(null);const [employee,setEmployee]=useState('');const [category,setCategory]=useState('');const [note,setNote]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [error,setError]=useState('');useEffect(()=>{getAttendanceKioskData(token).then(d=>{setData(d);setEmployee(d.employees?.[0]?.id??'');setCategory(d.categories?.[0]?.id??'')}).catch(e=>setError(e instanceof Error?e.message:'Link no valido'))},[token]);const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');setMessage('');try{const r=await markAttendance(token,employee,category,note);setMessage(`${r.employeeName} - ${r.categoryName} registrado a las ${new Date(r.markedAt).toLocaleTimeString('es-GT')}`);setNote('')}catch(err){setError(err instanceof Error?err.message:'No fue posible registrar')}finally{setBusy(false)}};if(!data&&!error)return <div className="app-loading"><div className="brand-mark"><CalendarDays/></div><span>Cargando marcador...</span></div>;return <main className="auth-page"><section className="auth-showcase"><div className="auth-brand"><div className="brand-mark"><CalendarDays/></div><b>{data?.business?.name??'Asistencia'}</b></div><div className="auth-copy"><span>CONTROL DE ASISTENCIA</span><h1>Marca tu<br/>jornada.</h1><p className="brand-slogan">La hora se guarda automaticamente.</p></div><div className="auth-quote">{data?.branch?.name??'Marcaje general'}</div></section><section className="auth-form-wrap"><form className="auth-form" onSubmit={submit}><span className="eyebrow">MARCAJE QR</span><h2>Selecciona tu asistencia</h2><p>Si trabajaste medio dia o no marcaste almuerzo, igual puedes seleccionar Terminar dia.</p>{error&&<div className="auth-message error">{error}</div>}{data&&<><label>Empleado<select value={employee} onChange={e=>setEmployee(e.target.value)}>{data.employees.map((e:any)=><option key={e.id} value={e.id}>{e.fullName}</option>)}</select></label><label>Categoria<select value={category} onChange={e=>setCategory(e.target.value)}>{data.categories.map((c:any)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Nota opcional<input value={note} onChange={e=>setNote(e.target.value)} placeholder="Ej. turno noche, permiso, medio dia"/></label>{message&&<div className="auth-message notice">{message}</div>}<button className="auth-submit" disabled={busy||!employee||!category}>{busy?<><RefreshCw className="spin"/>Registrando...</>:'Registrar asistencia'}</button></>}</form></section></main>}

const qrOptions={errorCorrectionLevel:'Q' as const,margin:4,color:{dark:'#111111',light:'#ffffff'}}
async function qrDataUrl(value:string,pixels=240){return QRCode.toDataURL(value,{...qrOptions,width:pixels})}
async function qrImgMarkup(value:string,pixels=320){const src=await qrDataUrl(value,pixels);return `<img src="${src}" width="${pixels}" height="${pixels}" alt="QR" style="display:block;margin:16px auto;background:#fff"/>`}
function qrAbsoluteUrl(value:string){try{const url=new URL(String(value||'').trim(),window.location.origin);if(url.origin===window.location.origin)return url.toString();const token=extractAttendanceQrV2Token(url.toString());if(token)return new URL(`/asistencia/qr/${encodeURIComponent(token)}`,window.location.origin).toString();return new URL('/asistencia/qr/',window.location.origin).toString()}catch{const token=extractAttendanceQrV2Token(value);if(token)return new URL(`/asistencia/qr/${encodeURIComponent(token)}`,window.location.origin).toString();return new URL(String(value||'').trim(),window.location.origin).toString()}}
function LocalQr({value,size=240}:{value:string;size?:number}){const [src,setSrc]=useState('');const [error,setError]=useState('');useEffect(()=>{let active=true;setSrc('');setError('');qrDataUrl(value,size).then(next=>{if(active)setSrc(next)}).catch(()=>{if(active)setError('No fue posible generar el QR visual.')});return()=>{active=false}},[value,size]);if(error)return <div className="auth-message error">{error}</div>;if(!src)return <div className="auth-message notice">Generando QR...</div>;return <img className="local-qr" src={src} width={size} height={size} alt="QR de asistencia"/>}function AttendanceQrV2Admin({profile,branches}:{profile:StoreProfile;branches:Branch[]}){
  const today=new Date().toISOString().slice(0,10)
  const categoryLabel=(value:string|null|undefined)=>({nino:'Nino',joven:'Joven',adulto:'Adulto'}[value||'']??'Pendiente')
  const ageFromBirthDate=(birthDate:string)=>{const clean=String(birthDate||'').slice(0,10);const b=new Date(`${clean}T00:00:00`);if(!clean||Number.isNaN(b.getTime()))return 0;const now=new Date();let age=now.getFullYear()-b.getFullYear();const m=now.getMonth()-b.getMonth();if(m<0||(m===0&&now.getDate()<b.getDate()))age--;return Math.max(0,age)}
  const suggestedCategory=(birthDate:string)=>{const age=ageFromBirthDate(birthDate);return age<=12?'nino':age<=17?'joven':'adulto'}
  const [settings,setSettings]=useState<AttendanceSettings|null>(null);const [people,setPeople]=useState<AttendancePersonV2[]>([]);const [records,setRecords]=useState<AttendanceDailyRecordV2[]>([]);const [date,setDate]=useState(today);const [form,setForm]=useState({fullName:'',birthDate:'',sex:'no_especificado',categoryOverride:'',branchId:profile.branchId});const [busy,setBusy]=useState('');const [error,setError]=useState('');const [lastLink,setLastLink]=useState<{personId:string;personName:string;url:string}|null>(null);const [readerLink,setReaderLink]=useState<{readerId:string|null;url:string}|null>(null)
  const formAge=form.birthDate?ageFromBirthDate(form.birthDate):null
  const formSuggested=form.birthDate?suggestedCategory(form.birthDate):null
  const refreshRecords=async(showError=true)=>{try{setRecords(await loadAttendanceDailyRecordsV2(profile,date))}catch(e){if(showError)setError(e instanceof Error?e.message:'No fue posible actualizar reporte diario V2')}}
  const refresh=async()=>{setError('');try{const [s,p,r]=await Promise.all([loadAttendanceSettings(profile),loadAttendancePeopleV2(profile),loadAttendanceDailyRecordsV2(profile,date)]);setSettings(s);setPeople(p);setRecords(r)}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar Asistencia V2')}}
  useEffect(()=>{refresh()},[date])
  useEffect(()=>{const tick=()=>refreshRecords(false);const id=window.setInterval(tick,15000);const onFocus=()=>tick();const onVisibility=()=>{if(document.visibilityState==='visible')tick()};window.addEventListener('focus',onFocus);document.addEventListener('visibilitychange',onVisibility);return()=>{window.clearInterval(id);window.removeEventListener('focus',onFocus);document.removeEventListener('visibilitychange',onVisibility)}},[date,profile.businessId])
  const saveMode=async(next:Partial<AttendanceSettings>)=>{if(!settings)return;setBusy('settings');try{await saveAttendanceSettings(profile,{...settings,...next});await refresh()}catch(e){setError(e instanceof Error?e.message:'No fue posible guardar configuracion')}finally{setBusy('')}}
  const createPerson=async(e:React.FormEvent)=>{e.preventDefault();setBusy('person');setError('');try{await createAttendancePersonV2(profile,{...form,categoryOverride:form.categoryOverride||null});setForm({fullName:'',birthDate:'',sex:'no_especificado',categoryOverride:'',branchId:profile.branchId});await refresh()}catch(err){setError(err instanceof Error?err.message:'No fue posible crear persona')}finally{setBusy('')}}
  const togglePerson=async(person:AttendancePersonV2)=>{setBusy(person.id);try{await updateAttendancePersonV2(person.id,{active:!person.active});await refresh()}catch(e){setError(e instanceof Error?e.message:'No fue posible actualizar persona')}finally{setBusy('')}}
  const generate=async(person:AttendancePersonV2)=>{setBusy(person.id);setError('');try{const result=await generateAttendanceQrV2(person.id);if(!result.link)throw new Error('No fue posible construir el link publico');const link={personId:person.id,personName:person.fullName,url:qrAbsoluteUrl(result.link)};setLastLink(link);await refresh();navigator.clipboard?.writeText(link.url)}catch(e){setError(e instanceof Error?e.message:'No fue posible generar QR')}finally{setBusy('')}}
  const revoke=async(person:AttendancePersonV2)=>{if(!person.tokenId)return;if(!confirm(`Revocar QR de ${person.fullName}?`))return;setBusy(person.id);try{await revokeAttendanceQrV2(person.tokenId);if(lastLink?.personId===person.id)setLastLink(null);await refresh()}catch(e){setError(e instanceof Error?e.message:'No fue posible revocar QR')}finally{setBusy('')}}
  const printCard=async(person:AttendancePersonV2)=>{const link=lastLink?.personId===person.id?lastLink.url:'Genera nuevamente el link para imprimirlo. El token plano no se guarda por seguridad.';const qr=lastLink?.personId===person.id?await qrImgMarkup(link,320):'';printHtml('Tarjeta QR V2',`<h1>${profile.businessName}</h1><p><b>${person.fullName}</b></p>${qr}<p style="font-size:16px;word-break:break-all">${link}</p><p>El token plano solo se muestra al generar/regenerar. Si se pierde, debe regenerarse.</p>`)}
  const generateReader=async()=>{setBusy('reader');setError('');try{const result=await generateAttendanceReaderV2(profile.businessId);if(!result.link)throw new Error('No fue posible construir el link lector');setReaderLink({readerId:result.readerId,url:result.link});navigator.clipboard?.writeText(result.link)}catch(e){const message=e instanceof Error?e.message:'No fue posible generar el lector';setError(message.startsWith('No fue posible generar el lector')?message:`No fue posible generar el lector: ${message}`)}finally{setBusy('')}}
  const revokeReader=async()=>{if(!readerLink?.readerId)return;if(!confirm('Revocar lector QR de empresa?'))return;setBusy('reader');setError('');try{await revokeAttendanceReaderV2(readerLink.readerId);setReaderLink(null)}catch(e){setError(e instanceof Error?e.message:'No fue posible revocar lector QR')}finally{setBusy('')}}
  return <><section className="card"><CardHead title="Asistencia QR V2" sub="Modo por empresa completa; la asistencia legacy queda intacta."/><div className="movement-filters"><select value={settings?.attendanceMode??'legacy'} onChange={e=>saveMode({attendanceMode:e.target.value as any})} disabled={!settings||busy==='settings'}><option value="legacy">Legacy por kiosco</option><option value="employee_qr_v2">QR V2 por empleado</option></select><label><input type="checkbox" checked={settings?.usesLunch??true} onChange={e=>saveMode({usesLunch:e.target.checked})}/> Usa almuerzo</label><label><input type="checkbox" checked={settings?.allowsHalfDay??true} onChange={e=>saveMode({allowsHalfDay:e.target.checked})}/> Medio dia</label><label><input type="checkbox" checked={settings?.allowsContinuousDay??true} onChange={e=>saveMode({allowsContinuousDay:e.target.checked})}/> Jornada continua</label></div><div className="tenant-security-note"><b>Lector QR de empresa</b><span>Genera un link unico para que el encargado abra camara, escanee QR personales y registre asistencia sin login.</span></div><div className="dialog-actions"><button type="button" className="primary" disabled={busy==='reader'} onClick={generateReader}><ScanBarcode/>{busy==='reader'?'Generando...':'Generar/regenerar lector QR'}</button>{readerLink?.readerId&&<button type="button" className="danger-outline" disabled={busy==='reader'} onClick={revokeReader}><Power/>Revocar lector</button>}</div>{readerLink&&<div className="auth-message notice"><b>Link lector QR V2</b><input readOnly value={readerLink.url}/><div className="dialog-actions"><button type="button" className="secondary" onClick={()=>navigator.clipboard?.writeText(readerLink.url)}>Copiar</button><button type="button" className="secondary" onClick={()=>window.open(readerLink.url,'_blank','noopener')}>Abrir</button><button type="button" className="primary" onClick={()=>printHtml('Lector Asistencia QR V2',`<h1>Lector Asistencia QR V2</h1><p>${profile.businessName}</p><p style="font-size:16px;word-break:break-all">${readerLink.url}</p><p>Este link es para el encargado. No lo publiques fuera de la empresa.</p>`)}>Imprimir link</button></div><span>El token plano solo se muestra al generar/regenerar. En base de datos queda token_hash.</span></div>}{lastLink&&<div className="auth-message notice"><b>Link publico generado para {lastLink.personName}</b><LocalQr value={lastLink.url} size={240}/><label>Contenido del QR<input readOnly value={lastLink.url}/></label><div className="dialog-actions"><button type="button" className="secondary" onClick={()=>navigator.clipboard?.writeText(lastLink.url)}>Copiar</button><button type="button" className="secondary" onClick={()=>window.open(lastLink.url,'_blank','noopener')}>Abrir</button><button type="button" className="primary" onClick={async()=>printHtml('Link Asistencia QR V2',`<h1>Asistencia QR V2</h1><p><b>${lastLink.personName}</b></p>${await qrImgMarkup(lastLink.url,320)}<p style="font-size:16px;word-break:break-all">${lastLink.url}</p><p>El token plano solo se muestra al generar/regenerar. Si se pierde, debe regenerarse.</p>`)}>Imprimir link</button></div><span>El token plano solo se muestra al generar/regenerar. Si se pierde, debe regenerarse. Por seguridad solo se guarda token_hash en la base.</span></div>}{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}</section><section className="card movement-table"><CardHead title="Personas QR V2" sub="Crea personas de asistencia independientes del usuario de login."/><form className="dialog-grid" onSubmit={createPerson}><label>Nombre completo<input required value={form.fullName} onChange={e=>setForm({...form,fullName:e.target.value})}/></label><label>Fecha de nacimiento<input required type="date" value={form.birthDate} onChange={e=>setForm({...form,birthDate:e.target.value})}/>{formAge!==null&&<span className="subline">Edad: {formAge} anos - sugerida: {categoryLabel(formSuggested)}</span>}</label><label>Sexo<select value={form.sex} onChange={e=>setForm({...form,sex:e.target.value})}><option value="no_especificado">No especificado</option><option value="masculino">Masculino</option><option value="femenino">Femenino</option></select></label><label>Categoria manual<select value={form.categoryOverride} onChange={e=>setForm({...form,categoryOverride:e.target.value})}><option value="">Sugerida por edad</option><option value="nino">Nino</option><option value="joven">Joven</option><option value="adulto">Adulto</option></select>{formSuggested&&<span className="subline">Final: {categoryLabel(form.categoryOverride||formSuggested)}</span>}</label><label>Sucursal<select value={form.branchId} onChange={e=>setForm({...form,branchId:e.target.value})}>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select></label><button className="primary" disabled={busy==='person'}><Plus/>{busy==='person'?'Creando...':'Crear persona'}</button></form><div className="table-scroll"><table><thead><tr><th>Persona</th><th>Nacimiento</th><th>Edad</th><th>Categoria sugerida</th><th>Categoria final</th><th>Sexo</th><th>Sucursal</th><th>Estado</th><th>QR</th><th>Acciones</th></tr></thead><tbody>{people.map(p=>{const suggested=suggestedCategory(p.birthDate);return <tr key={p.id}><td><b>{p.fullName}</b></td><td>{p.birthDate}</td><td>{p.age}</td><td>{categoryLabel(suggested)}</td><td><b>{categoryLabel(p.category)}</b>{p.categoryOverride&&<span className="subline">Override manual</span>}</td><td>{p.sex}</td><td>{p.branchName}</td><td><span className={p.active?'badge success':'badge neutral'}>{p.active?'Activa':'Inactiva'}</span></td><td><span className={p.tokenActive?'badge success':'badge neutral'}>{p.tokenActive?'Activo':'Sin QR'}</span></td><td><div className="tenant-actions"><button title="Generar o regenerar link QR" disabled={busy===p.id||!p.active} onClick={()=>generate(p)}><RefreshCw/></button>{p.tokenId&&<button title="Revocar QR" disabled={busy===p.id} onClick={()=>revoke(p)}><Power/></button>}<button title="Imprimir tarjeta" onClick={()=>printCard(p)}><Download/></button><button title={p.active?'Inactivar':'Activar'} disabled={busy===p.id} onClick={()=>togglePerson(p)}>{p.active?<Trash2/>:<CheckCircle2/>}</button></div></td></tr>})}</tbody></table>{people.length===0&&<div className="empty-table"><Users/><b>Sin personas QR V2</b><span>Crea una persona para generar su link personalizado.</span></div>}</div></section><AttendanceV3Admin profile={profile} branches={branches}/><section className="card movement-table"><CardHead title="Reporte diario V2" sub="Resumen basico del dia seleccionado." action={<div className="dialog-actions"><input type="date" value={date} onChange={e=>setDate(e.target.value)}/><button type="button" className="secondary" disabled={busy==='records'} onClick={async()=>{setBusy('records');setError('');try{await refreshRecords()}finally{setBusy('')}}}><RefreshCw className={busy==='records'?'spin':''}/>Actualizar</button></div>}/><div className="table-scroll"><table><thead><tr><th>Persona</th><th>Sucursal</th><th>Estado</th><th>Entrada</th><th>Almuerzo</th><th>Regreso</th><th>Salida</th><th>Minutos</th><th>Flags</th></tr></thead><tbody>{records.map(r=><tr key={r.id}><td><b>{r.personName}</b></td><td>{r.branchName}</td><td>{r.status}</td><td>{r.checkInAt?new Date(r.checkInAt).toLocaleTimeString('es-GT'):''}</td><td>{r.lunchOutAt?new Date(r.lunchOutAt).toLocaleTimeString('es-GT'):''}</td><td>{r.lunchInAt?new Date(r.lunchInAt).toLocaleTimeString('es-GT'):''}</td><td>{r.checkOutAt?new Date(r.checkOutAt).toLocaleTimeString('es-GT'):''}</td><td>{r.totalWorkedMinutes}</td><td>{Object.keys(r.flags??{}).join(', ')}</td></tr>)}</tbody></table>{records.length===0&&<div className="empty-table"><CalendarDays/><b>Sin marcajes V2 para este dia</b></div>}</div></section></>
}
function AttendanceV3Admin({profile,branches}:{profile:StoreProfile;branches:Branch[]}){const today=new Date().toISOString().slice(0,10);const [movements,setMovements]=useState<AttendanceMovementV3[]>([]);const [events,setEvents]=useState<AttendanceEventV3[]>([]);const [from,setFrom]=useState(today);const [to,setTo]=useState(today);const [branch,setBranch]=useState('');const [form,setForm]=useState({name:'',category:'',description:'',sortOrder:'100',color:'#278d57',icon:'',requiresNote:false});const [readerLink,setReaderLink]=useState('');const [busy,setBusy]=useState('');const [error,setError]=useState('');const refresh=async()=>{setError('');try{const [m,r]=await Promise.all([listAttendanceMovementsV3(),getAttendanceReportV3(from,to,branch||undefined)]);setMovements(m);setEvents(r)}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar Asistencia V3')}};useEffect(()=>{refresh()},[from,to,branch]);const create=async(e:React.FormEvent)=>{e.preventDefault();setBusy('movement');setError('');try{await createAttendanceMovementV3({...form,sortOrder:Number(form.sortOrder)});setForm({name:'',category:'',description:'',sortOrder:'100',color:'#278d57',icon:'',requiresNote:false});await refresh()}catch(err){setError(err instanceof Error?err.message:'No fue posible crear movimiento V3')}finally{setBusy('')}};const toggle=async(m:AttendanceMovementV3)=>{setBusy(m.id);setError('');try{await updateAttendanceMovementV3({movementId:m.id,name:m.name,category:m.category,description:m.description,active:!m.active,sortOrder:m.sortOrder,color:m.color,icon:m.icon,requiresNote:m.requiresNote});await refresh()}catch(e){setError(e instanceof Error?e.message:'No fue posible actualizar movimiento V3')}finally{setBusy('')}};const initialize=async()=>{setBusy('init');setError('');try{setMovements(await initializeAttendanceMovementsV3());await refresh()}catch(e){setError(e instanceof Error?e.message:'No fue posible inicializar movimientos V3')}finally{setBusy('')}};const generateReader=async()=>{setBusy('readerV3');setError('');try{const r=await generateAttendanceReaderV3(profile.businessId);setReaderLink(r.link);navigator.clipboard?.writeText(r.link)}catch(e){setError(e instanceof Error?e.message:'No fue posible generar lector V3')}finally{setBusy('')}};return <section className="card movement-table"><CardHead title="Movimientos V3" sub="Asistencia flexible: el encargado selecciona movimientos configurados por empresa." action={<div className="dialog-actions"><button type="button" className="secondary" disabled={busy==='init'} onClick={initialize}><RefreshCw/>Inicializar</button><button type="button" className="primary" disabled={busy==='readerV3'} onClick={generateReader}><ScanBarcode/>Lector V3</button></div>}/><div className="tenant-security-note"><ShieldCheck/><span><b>Modelo flexible</b>No usa allowedActions por estado ni secuencia entrada/almuerzo/salida. Solo valida empresa, lector, persona, movimiento activo y anti-duplicado simple.</span></div>{readerLink&&<div className="auth-message notice"><b>Link lector V3</b><input readOnly value={readerLink}/><div className="dialog-actions"><button type="button" className="secondary" onClick={()=>navigator.clipboard?.writeText(readerLink)}>Copiar</button><button type="button" className="secondary" onClick={()=>window.open(readerLink,'_blank','noopener')}>Abrir</button></div></div>}{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<form className="dialog-grid" onSubmit={create}><label>Movimiento<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Ej. Visita a obra"/></label><label>Categoria<input value={form.category} onChange={e=>setForm({...form,category:e.target.value})} placeholder="jornada, permiso, externo"/></label><label>Orden<input type="number" value={form.sortOrder} onChange={e=>setForm({...form,sortOrder:e.target.value})}/></label><label>Color<input value={form.color} onChange={e=>setForm({...form,color:e.target.value})}/></label><label className="full">Descripcion<input value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label><input type="checkbox" checked={form.requiresNote} onChange={e=>setForm({...form,requiresNote:e.target.checked})}/> Requiere nota</label><button className="primary" disabled={busy==='movement'}><Plus/>{busy==='movement'?'Creando...':'Crear movimiento'}</button></form><div className="table-scroll"><table><thead><tr><th>Movimiento</th><th>Categoria</th><th>Orden</th><th>Nota</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>{movements.map(m=><tr key={m.id}><td><b>{m.name}</b><span className="subline">{m.description||'Sin descripcion'}</span></td><td>{m.category||'General'}</td><td>{m.sortOrder}</td><td>{m.requiresNote?'Obligatoria':'Opcional'}</td><td><span className={m.active?'badge success':'badge neutral'}>{m.active?'Activo':'Inactivo'}</span></td><td><button type="button" className="secondary" disabled={busy===m.id} onClick={()=>toggle(m)}>{m.active?'Inactivar':'Activar'}</button></td></tr>)}</tbody></table>{movements.length===0&&<div className="empty-table"><CalendarDays/><b>Sin movimientos V3</b><span>Inicializa valores por defecto o crea un movimiento personalizado.</span></div>}</div><CardHead title="Reporte V3" sub="Eventos registrados por movimiento configurable." action={<div className="dialog-actions"><input type="date" value={from} onChange={e=>setFrom(e.target.value)}/><input type="date" value={to} onChange={e=>setTo(e.target.value)}/><select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><button type="button" className="secondary" onClick={refresh}><RefreshCw/>Actualizar</button></div>}/><div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Persona</th><th>Sucursal</th><th>Movimiento</th><th>Categoria</th><th>Origen</th><th>Nota</th></tr></thead><tbody>{events.map(ev=><tr key={ev.eventId}><td>{new Date(ev.occurredAt).toLocaleString('es-GT')}</td><td><b>{ev.personName}</b></td><td>{ev.branchName}</td><td>{ev.movementName}</td><td>{ev.movementCategory||'General'}</td><td>{ev.source}</td><td>{ev.note||''}</td></tr>)}</tbody></table>{events.length===0&&<div className="empty-table"><Search/><b>Sin eventos V3 en este periodo</b></div>}</div></section>}
function extractAttendanceQrV2Token(value:string){const text=String(value||'').trim();const tokenPattern=/^[A-Za-z0-9_-]{24,}$/;const cleanToken=(raw:string|null|undefined)=>{const token=decodeURIComponent(String(raw??'').trim()).replace(/^\/+|\/+$/g,'');return tokenPattern.test(token)?token:''};if(!text)return '';try{const url=new URL(text,window.location.origin);const path='/asistencia/qr/';if(url.pathname.startsWith(path))return cleanToken(url.pathname.slice(path.length));return cleanToken(url.searchParams.get('attendanceQrV2')||url.searchParams.get('attendance'))}catch{if(text.startsWith('/asistencia/qr/'))return cleanToken(text.slice('/asistencia/qr/'.length));if(text.startsWith('?')){try{return cleanToken(new URL(text,window.location.origin).searchParams.get('attendanceQrV2')||new URL(text,window.location.origin).searchParams.get('attendance'))}catch{return ''}}return cleanToken(text)}}
function AttendanceReaderV3Public({token}:{token:string}){const videoRef=useRef<HTMLVideoElement|null>(null);const streamRef=useRef<MediaStream|null>(null);const scanningRef=useRef(false);const scanLockRef=useRef(false);const candidateRef=useRef<AttendanceV3ValidateResult|null>(null);const [candidate,setCandidate]=useState<AttendanceV3ValidateResult|null>(null);const [employeeToken,setEmployeeToken]=useState('');const [note,setNote]=useState('');const [busy,setBusy]=useState('');const [message,setMessage]=useState('');const [error,setError]=useState('');const [cameraActive,setCameraActive]=useState(false);const [scanStatus,setScanStatus]=useState('Inicializando camara...');const [lastRaw,setLastRaw]=useState('');const maskQrValue=(value:string)=>{const clean=String(value||'').trim();return clean.length>34?`${clean.slice(0,24)}...${clean.slice(-8)}`:clean};useEffect(()=>{candidateRef.current=candidate},[candidate]);const validateEmployee=async(raw:string)=>{setLastRaw(maskQrValue(raw));const employee=extractAttendanceQrV2Token(raw);if(!employee){setScanStatus('QR detectado sin token valido');setError('QR detectado, pero no contiene un token valido.');return}if(candidateRef.current||scanLockRef.current)return;scanLockRef.current=true;setBusy('scan');setMessage('');setError('');setScanStatus('QR detectado. Validando persona...');try{const data=await validateAttendanceEmployeeV3(token,employee);setEmployeeToken(employee);setCandidate(data);setScanStatus('Persona validada. Selecciona movimiento.')}catch(e){setScanStatus('Validacion rechazada');setError(e instanceof Error?e.message:'QR no valido para Asistencia V3')}finally{scanLockRef.current=false;setBusy('')}};const startCamera=async()=>{setError('');setScanStatus('Solicitando camara...');const detectorCtor=(window as any).BarcodeDetector;if(!detectorCtor){setError('Este navegador no tiene lector QR nativo. Usa Chrome o Edge actualizado.');setScanStatus('BarcodeDetector no disponible');return}try{const detector=new detectorCtor({formats:['qr_code']});const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});streamRef.current=stream;if(videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play()}setCameraActive(true);setScanStatus('Buscando QR...');scanningRef.current=true;const scan=async()=>{if(!scanningRef.current)return;if(videoRef.current&&videoRef.current.readyState>=2&&videoRef.current.videoWidth>0&&!candidateRef.current&&!scanLockRef.current){try{const codes=await detector.detect(videoRef.current);const raw=String(codes?.[0]?.rawValue||'');if(raw)await validateEmployee(raw)}catch{}}requestAnimationFrame(scan)};requestAnimationFrame(scan)}catch(e){setCameraActive(false);setScanStatus('Camara no disponible');setError(e instanceof Error?e.message:'No fue posible abrir la camara')}};useEffect(()=>{startCamera();return()=>{scanningRef.current=false;setCameraActive(false);streamRef.current?.getTracks().forEach(track=>track.stop())}},[token]);const record=async(movement:AttendanceMovementV3)=>{if(!employeeToken)return;if(movement.requiresNote&&!note.trim()){setError('Este movimiento requiere nota.');return}setBusy(movement.id);setMessage('');setError('');try{const result=await recordAttendanceMovementV3(token,employeeToken,movement.id,note);setMessage(result.message||'Movimiento registrado correctamente.');setCandidate(null);candidateRef.current=null;setEmployeeToken('');setNote('');setLastRaw('');setScanStatus('Registro guardado. Buscando QR...')}catch(e){setError(e instanceof Error?e.message:'No fue posible registrar movimiento V3')}finally{setBusy('')}};const rescan=()=>{setCandidate(null);candidateRef.current=null;setEmployeeToken('');setNote('');setMessage('Listo para escanear otro QR.');setScanStatus('Buscando QR...')};return <main className="auth-page"><section className="auth-showcase"><div className="auth-brand"><div className="brand-mark"><CalendarDays/></div><b>Asistencia V3</b></div><div className="auth-copy"><span>LECTOR FLEXIBLE</span><h1>Registra<br/>movimientos.</h1><p className="brand-slogan">Escanea una persona y selecciona el movimiento configurado.</p></div><div className="auth-quote">Sin reglas rigidas</div></section><section className="auth-form-wrap"><div className="auth-form"><span className="eyebrow">LECTOR QR V3</span><h2>{candidate?.businessName??'Asistencia configurable'}</h2>{error&&<div className="auth-message error">{error}</div>}{message&&<div className="auth-message notice">{message}</div>}<video ref={videoRef} className="qr-reader-video" autoPlay playsInline muted/><div className="auth-message notice"><b>Diagnostico lector</b><span>Camara activa: {cameraActive?'Si':'No'}</span><span>Estado: {scanStatus}</span>{lastRaw&&<span>Ultimo QR detectado: {lastRaw}</span>}</div>{busy==='scan'&&<div className="auth-message notice"><RefreshCw className="spin"/>Validando QR...</div>}{candidate&&<><div className="connection-banner"><div className="connected"><CheckCircle2/></div><div><b>{candidate.person.fullName}</b><span>{candidate.person.branchName} - {candidate.person.category} - {candidate.person.age} anos</span></div></div><label>Nota opcional<input value={note} onChange={e=>setNote(e.target.value)} placeholder="Motivo, obra, permiso o detalle"/></label>{candidate.movements.length===0?<div className="empty-table"><AlertTriangle/><b>Sin movimientos activos</b><span>Un administrador debe configurar movimientos V3.</span><button type="button" className="secondary" onClick={rescan}>Escanear otro QR</button></div>:<div className="dialog-actions">{candidate.movements.map(m=><button key={m.id} type="button" className="primary" disabled={Boolean(busy)} onClick={()=>record(m)}>{busy===m.id?<RefreshCw className="spin"/>:<ScanBarcode/>}{m.name}</button>)}<button type="button" className="secondary" disabled={Boolean(busy)} onClick={rescan}>Cancelar</button></div>}</>}</div></section></main>}function AttendanceReaderV2Public({token}:{token:string}){const videoRef=useRef<HTMLVideoElement|null>(null);const streamRef=useRef<MediaStream|null>(null);const scanningRef=useRef(false);const scanLockRef=useRef(false);const candidateRef=useRef<AttendanceReaderEmployeeResolveResult|null>(null);const [reader,setReader]=useState<AttendanceReaderResolveResult|null>(null);const [candidate,setCandidate]=useState<AttendanceReaderEmployeeResolveResult|null>(null);const [employeeToken,setEmployeeToken]=useState('');const [busy,setBusy]=useState('');const [message,setMessage]=useState('');const [error,setError]=useState('');const [cameraActive,setCameraActive]=useState(false);const [scanStatus,setScanStatus]=useState('Inicializando camara...');const [lastRaw,setLastRaw]=useState('');const [lastExtract,setLastExtract]=useState(false);const maskQrValue=(value:string)=>{const clean=String(value||'').trim();return clean.length>34?`${clean.slice(0,24)}...${clean.slice(-8)}`:clean};const label=(action:string)=>({check_in:'Registrar entrada',lunch_out:'Salida a almuerzo',lunch_in:'Regreso de almuerzo',check_out:'Salida final',half_day_out:'Medio dia',continuous_day_out:'Jornada continua'}[action]??action);useEffect(()=>{candidateRef.current=candidate},[candidate]);useEffect(()=>{let active=true;resolveAttendanceReaderV2(token).then(data=>{if(active)setReader(data)}).catch(e=>{if(active)setError(e instanceof Error?e.message:'Lector no valido o inactivo')});return()=>{active=false;streamRef.current?.getTracks().forEach(track=>track.stop())}},[token]);const validateEmployee=async(raw:string)=>{setLastRaw(maskQrValue(raw));const employee=extractAttendanceQrV2Token(raw);setLastExtract(Boolean(employee));if(!employee){setScanStatus('QR detectado sin token valido');setError('QR detectado, pero no contiene un token valido.');return}if(candidateRef.current||scanLockRef.current)return;scanLockRef.current=true;setBusy('scan');setMessage('');setError('');setScanStatus('QR detectado. Validando empleado...');try{const data=await validateAttendanceReaderEmployeeV2(token,employee);setEmployeeToken(employee);setCandidate(data);setScanStatus('QR validado')}catch(e){setScanStatus('QR detectado, validacion rechazada');setError(e instanceof Error?e.message:'QR de empleado no valido para esta empresa')}finally{scanLockRef.current=false;setBusy('')}};const startCamera=async()=>{setError('');setScanStatus('Solicitando camara...');const detectorCtor=(window as any).BarcodeDetector;if(!detectorCtor){setError('Este navegador no tiene lector QR nativo. Usa Chrome o Edge actualizado.');setScanStatus('BarcodeDetector no disponible');return}try{const detector=new detectorCtor({formats:['qr_code']});const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});streamRef.current=stream;if(videoRef.current){videoRef.current.srcObject=stream;await videoRef.current.play()}setCameraActive(true);setScanStatus('Buscando QR...');scanningRef.current=true;const scan=async()=>{if(!scanningRef.current)return;if(videoRef.current&&videoRef.current.readyState>=2&&videoRef.current.videoWidth>0&&!candidateRef.current&&!scanLockRef.current){try{const codes=await detector.detect(videoRef.current);const raw=String(codes?.[0]?.rawValue||'');if(raw)await validateEmployee(raw)}catch{}}requestAnimationFrame(scan)};requestAnimationFrame(scan)}catch(e){setCameraActive(false);setScanStatus('Camara no disponible');setError(e instanceof Error?e.message:'No fue posible abrir la camara')}};useEffect(()=>{if(reader)startCamera();return()=>{scanningRef.current=false;setCameraActive(false);streamRef.current?.getTracks().forEach(track=>track.stop())}},[reader]);const record=async(action:string)=>{if(!employeeToken)return;setBusy(action);setMessage('');setError('');try{const result=await recordAttendanceReaderEmployeeV2(token,employeeToken,action);setMessage(result.message||'Registro guardado correctamente.');setCandidate(null);candidateRef.current=null;setEmployeeToken('');setLastExtract(false);setLastRaw('');setScanStatus('Registro guardado correctamente. Buscando QR...')}catch(e){setError(e instanceof Error?e.message:'No fue posible registrar asistencia')}finally{setBusy('')}};const rescan=()=>{setCandidate(null);setEmployeeToken('');setLastExtract(false);setMessage('Listo para escanear otro QR.');setScanStatus('Buscando QR...')};if(!reader&&!error)return <div className="app-loading"><div className="brand-mark"><ScanBarcode/></div><span>Cargando lector QR V2...</span></div>;return <main className="auth-page"><section className="auth-showcase"><div className="auth-brand"><div className="brand-mark"><CalendarDays/></div><b>Asistencia V2</b></div><div className="auth-copy"><span>LECTOR QR DE EMPRESA</span><h1>Escanea<br/>asistencia.</h1><p className="brand-slogan">El encargado registra QR personales sin login.</p></div><div className="auth-quote">{reader?.businessName??'Lector QR'}</div></section><section className="auth-form-wrap"><div className="auth-form"><span className="eyebrow">LECTOR QR V2</span><h2>{reader?.businessName??'Lector no disponible'}</h2>{error&&<div className="auth-message error">{error}</div>}{message&&<div className="auth-message notice">{message}</div>}<video ref={videoRef} className="qr-reader-video" autoPlay playsInline muted/><div className="auth-message notice"><b>Diagnostico lector</b><span>Camara activa: {cameraActive?'Si':'No'}</span><span>Estado: {scanStatus}</span>{lastRaw&&<span>Ultimo QR detectado: {lastRaw}</span>}<span>Token detectado: {lastExtract?'Si':'No'}</span></div>{busy==='scan'&&<div className="auth-message notice"><RefreshCw className="spin"/>Validando QR...</div>}{candidate&&<div className="connection-banner"><div className="connected"><CheckCircle2/></div><div><b>{candidate.person.fullName}</b><span>{candidate.person.category} - {candidate.person.age} anos - {candidate.daily.status}</span></div></div>}{candidate&&((candidate.allowedActions??[]).length===0?<div className="empty-table"><CheckCircle2/><b>Jornada cerrada</b><span>{candidate.message}</span><button type="button" className="secondary" onClick={rescan}>Escanear otro QR</button></div>:<div className="dialog-actions">{candidate.allowedActions.map(action=><button key={action} type="button" className="primary" disabled={Boolean(busy)} onClick={()=>record(action)}>{busy===action?<RefreshCw className="spin"/>:<ScanBarcode/>}{label(action)}</button>)}<button type="button" className="secondary" disabled={Boolean(busy)} onClick={rescan}>Cancelar</button></div>)}</div></section></main>}function AttendanceQrV2Public({token}:{token:string}){const [data,setData]=useState<any>(null);const [busy,setBusy]=useState('');const [message,setMessage]=useState('');const [error,setError]=useState('');const load=async()=>{setError('');try{setData(await resolveAttendanceQrV2(token))}catch(e){setError(e instanceof Error?e.message:'QR no valido o inactivo')}};useEffect(()=>{load()},[token]);const record=async(action:string)=>{setBusy(action);setMessage('');setError('');try{const result=await recordAttendanceQrV2(token,action);setMessage(result.message);await load()}catch(e){setError(e instanceof Error?e.message:'No fue posible registrar')}finally{setBusy('')}};const label=(action:string)=>({check_in:'Registrar entrada',lunch_out:'Salida a almuerzo',lunch_in:'Regreso de almuerzo',check_out:'Salida final',half_day_out:'Medio dia',continuous_day_out:'Jornada continua'}[action]??action);if(!data&&!error)return <div className="app-loading"><div className="brand-mark"><ScanBarcode/></div><span>Cargando QR V2...</span></div>;return <main className="auth-page"><section className="auth-showcase"><div className="auth-brand"><div className="brand-mark"><CalendarDays/></div><b>Asistencia V2</b></div><div className="auth-copy"><span>QR PERSONAL</span><h1>Marca tu<br/>jornada.</h1><p className="brand-slogan">Tu link es personal y permanente mientras este activo.</p></div><div className="auth-quote">Sin login</div></section><section className="auth-form-wrap"><div className="auth-form"><span className="eyebrow">MARCAJE QR V2</span><h2>{data?.person?.fullName??'QR no disponible'}</h2>{data?.person&&<p>{data.person.category} - {data.person.age} anos</p>}{error&&<div className="auth-message error">{error}</div>}{message&&<div className="auth-message notice">{message}</div>}{data&&<><div className="connection-banner"><div className="connected"><CheckCircle2/></div><div><b>Estado: {data.daily?.status}</b><span>Entrada: {data.daily?.checkInAt?new Date(data.daily.checkInAt).toLocaleTimeString('es-GT'):'pendiente'}</span></div></div>{(data.allowedActions??[]).length===0?<div className="empty-table"><CheckCircle2/><b>Jornada cerrada</b><span>No hay mas acciones disponibles por hoy.</span></div>:<div className="dialog-actions">{data.allowedActions.map((action:string)=><button key={action} type="button" className="primary" disabled={Boolean(busy)} onClick={()=>record(action)}>{busy===action?<RefreshCw className="spin"/>:<ScanBarcode/>}{label(action)}</button>)}</div>}</>}</div></section></main>}
function defaultAttendancePeriod():'first'|'second'{return new Date().getDate()<=15?'first':'second'}
function attendanceRange(period:'first'|'second'|'month'){const now=new Date();const from=new Date(now.getFullYear(),now.getMonth(),period==='second'?16:1);const to=period==='first'?new Date(now.getFullYear(),now.getMonth(),15,23,59,59):new Date(now.getFullYear(),now.getMonth()+1,0,23,59,59);return {from,to,label:period==='first'?'Primera quincena':period==='second'?'Segunda quincena':'Mes completo'}}
function attendanceWorkDays(range:{from:Date;to:Date},rule:'withSunday'|'withoutSunday'){let n=0;const d=new Date(range.from);d.setHours(12,0,0,0);const end=new Date(range.to);end.setHours(12,0,0,0);while(d<=end){if(rule==='withSunday'||d.getDay()!==0)n++;d.setDate(d.getDate()+1)}return Math.max(1,n)}
function isHalfShiftEvent(e:AttendanceEvent){const x=(e.categoryName+' '+e.categoryKind).toLowerCase();return x.includes('medio turno')||x.includes('medio dia')||x.includes('medio día')||x.includes('half')}
function attendancePayroll(employee:AttendanceEmployee,events:AttendanceEvent[],range:{from:Date;to:Date},rule:'withSunday'|'withoutSunday'='withoutSunday'){const byDay=new Map<string,AttendanceEvent[]>();events.forEach(e=>{const d=new Date(e.markedAt);if(rule==='withoutSunday'&&d.getDay()===0)return;const key=d.toDateString();byDay.set(key,[...(byDay.get(key)??[]),e])});const units=Array.from(byDay.values()).reduce((n,day)=>n+(day.some(isHalfShiftEvent)?0.5:1),0);const workingDays=attendanceWorkDays(range,rule);const earned=employee.baseSalary*Math.min(units,workingDays)/workingDays;return {employee,presentDays:units,workingDays,baseSalary:employee.baseSalary,earned}}
function printAttendanceReport(profile:StoreProfile,events:AttendanceEvent[],employees:AttendanceEmployee[],range:{from:Date;to:Date;label:string}){const rows=events.slice().reverse().map(e=>`<tr><td>${new Date(e.markedAt).toLocaleString('es-GT')}</td><td>${e.employeeName}</td><td>${e.categoryName}</td><td>${e.branchName}</td><td>${e.note}</td></tr>`).join('');printHtml('Control de asistencia',`<h1>${profile.businessName} / control de asistencia</h1><p>${range.label}: ${range.from.toLocaleDateString('es-GT')} al ${range.to.toLocaleDateString('es-GT')}</p><table><thead><tr><th>Fecha</th><th>Empleado</th><th>Categoria</th><th>Sucursal</th><th>Nota</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Sin marcajes</td></tr>'}</tbody></table>`)}
function printPayrollReport(profile:StoreProfile,rows:ReturnType<typeof attendancePayroll>[],range:{from:Date;to:Date;label:string},rule:'withSunday'|'withoutSunday'='withoutSunday'){const body=rows.map(r=>`<tr><td>${r.employee.fullName}</td><td>${r.presentDays}/${r.workingDays}</td><td>${money(r.baseSalary)}</td><td>${money(r.earned)}</td><td></td></tr>`).join('');const total=rows.reduce((n,r)=>n+r.earned,0);printHtml('Control de salarios',`<h1>GRUPO MULTIMARKETS S.A. ${profile.businessName} / cuadro de pago salarial</h1><p>QUINCENA: ${range.label} (${range.from.toLocaleDateString('es-GT')} - ${range.to.toLocaleDateString('es-GT')})</p><p>REGLA: ${rule==='withoutSunday'?'No se trabajan domingos':'Incluye domingos'}</p><table><thead><tr><th>Colaborador</th><th>Asistencia</th><th>Base quincenal</th><th>Total a recibir</th><th>Firma</th></tr></thead><tbody>${body}</tbody><tfoot><tr><td colspan="3"><b>TOTAL GENERAL</b></td><td><b>${money(total)}</b></td><td></td></tr></tfoot></table>`)}
function printHtml(title:string,body:string){const html=`<!doctype html><html><head><title>${title}</title><style>body{font-family:Georgia,serif;margin:18px;color:#000}h1{text-align:center;font-size:18px;text-transform:uppercase}table{width:100%;border-collapse:collapse}th,td{border:1px solid #111;padding:6px;font-size:13px}th{background:#f5f5f5}tfoot td{font-size:15px}@media print{button{display:none}}</style></head><body>${body}<br/><button onclick="window.print()">Imprimir</button><script>window.onload=function(){setTimeout(function(){window.print()},300)}</script></body></html>`;const w=window.open('','_blank','width=980,height=800');if(w){w.document.write(html);w.document.close()}}

function dateInputValue(d:Date){return d.toISOString().slice(0,10)}
function CorporateCashControl({profile}:{profile:StoreProfile}){const [rows,setRows]=useState<CorporateCashMovement[]>([]);const [branches,setBranches]=useState<Branch[]>([]);const [branch,setBranch]=useState('');const [from,setFrom]=useState(()=>{const d=new Date();d.setDate(d.getDate()-7);return dateInputValue(d)});const [to,setTo]=useState(()=>dateInputValue(new Date()));const [state,setState]=useState<'all'|'open'|'closed'>('all');const [dialog,setDialog]=useState<{mode:'edit'|'void';movement:CorporateCashMovement}|null>(null);const [loading,setLoading]=useState(false);const [error,setError]=useState('');useEffect(()=>{let alive=true;loadBranches(profile).then(b=>{if(!alive)return;setBranches(b);if(!branch&&b[0])setBranch(b[0].id)}).catch(e=>setError(e instanceof Error?e.message:'No fue posible cargar sucursales'));return()=>{alive=false}},[]);const refresh=async()=>{if(!branch)return;setLoading(true);setError('');try{const fromDate=new Date(`${from}T00:00:00`);const toDate=new Date(`${to}T23:59:59`);setRows(await loadCorporateCashMovements(branch,fromDate,toDate))}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar movimientos de caja')}finally{setLoading(false)}};useEffect(()=>{if(branch)refresh()},[branch,from,to]);const shown=rows.filter(r=>state==='all'||(state==='open'?r.isSessionOpen:!r.isSessionOpen));const totals=shown.reduce((a,r)=>({income:a.income+(r.status==='active'&&r.kind==='income'?r.amount:0),expense:a.expense+(r.status==='active'&&r.kind==='expense'?r.amount:0),voided:a.voided+(r.status==='voided'?1:0)}),{income:0,expense:0,voided:0});return <><div className="hub-section-head"><div><h3>Control de caja corporativo</h3><p>Edita o anula solo movimientos manuales activos de cajas abiertas.</p></div><button className="secondary" onClick={refresh} disabled={!branch||loading}><RefreshCw className={loading?'spin':''}/>Actualizar</button></div><div className="tenant-security-note"><ShieldCheck/><span><b>Regla financiera</b>Las cajas cerradas son solo lectura en esta version. Las anulaciones no borran registros y no afectan saldos.</span></div><div className="inventory-control-stats"><MiniStat label="Ingresos activos" value={money(totals.income)} icon={ArrowUpRight}/><MiniStat label="Retiros activos" value={money(totals.expense)} icon={ArrowDownRight}/><MiniStat label="Movimientos" value={String(shown.length)} icon={WalletCards}/><MiniStat label="Anulados" value={String(totals.voided)} icon={AlertTriangle} warn={totals.voided>0}/></div><div className="movement-filters card"><select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Selecciona sucursal</option>{branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</select><label>Desde<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>Hasta<input type="date" value={to} onChange={e=>setTo(e.target.value)}/></label><select value={state} onChange={e=>setState(e.target.value as any)}><option value="all">Todas las cajas</option><option value="open">Solo cajas abiertas</option><option value="closed">Solo cajas cerradas</option></select></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<section className="card movement-table">{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Cargando movimientos...</b></div>:<div className="table-scroll"><table><thead><tr><th>Fecha</th><th>Sucursal</th><th>Caja</th><th>Tipo</th><th>Descripcion</th><th>Usuario</th><th>Estado</th><th>Monto</th><th>Auditoria</th><th>Acciones</th></tr></thead><tbody>{shown.map(r=><tr key={r.movementId}><td>{new Date(r.movementCreatedAt).toLocaleString('es-GT')}</td><td><b>{r.branchName}</b></td><td><span className={r.isSessionOpen?'badge success':'badge neutral'}>{r.isSessionOpen?'Abierta':'Cerrada'}</span></td><td><span className="category-tag">{r.kind==='income'?'Ingreso':'Retiro'}</span></td><td>{r.description}</td><td>{r.createdByName}</td><td><span className={r.status==='active'?'badge success':'badge warning'}>{r.status==='active'?'Activo':'Anulado'}</span></td><td className={r.kind==='expense'?'negative-text':'positive-text'}>{r.kind==='expense'?'- ':'+ '}{money(r.amount)}</td><td>{r.lastAuditAt?<span className="subline">{new Date(r.lastAuditAt).toLocaleString('es-GT')}</span>:r.correctionReason||r.voidReason?<span className="subline">{r.correctionReason||r.voidReason}</span>:'-'}</td><td>{r.editable||r.voidable?<div className="tenant-actions">{r.editable&&<button title="Editar movimiento" onClick={()=>setDialog({mode:'edit',movement:r})}><Pencil/></button>}{r.voidable&&<button title="Anular movimiento" onClick={()=>setDialog({mode:'void',movement:r})}><Trash2/></button>}</div>:<span className="badge neutral">{r.status==='voided'?'Movimiento anulado':r.isSessionOpen?'No disponible':'Caja cerrada'}</span>}</td></tr>)}</tbody></table>{shown.length===0&&<div className="empty-table"><WalletCards/><b>Sin movimientos manuales para mostrar</b></div>}</div>}</section>{dialog&&<CorporateCashMovementDialog mode={dialog.mode} movement={dialog.movement} close={()=>setDialog(null)} saved={async()=>{setDialog(null);await refresh()}}/>}</>}
function CorporateCashMovementDialog({mode,movement,close,saved}:{mode:'edit'|'void';movement:CorporateCashMovement;close:()=>void;saved:()=>Promise<void>}){const [amount,setAmount]=useState(String(movement.amount));const [description,setDescription]=useState(movement.description);const [reason,setReason]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setError('');const cleanReason=reason.trim();if(cleanReason.length<10){setError('El motivo debe tener al menos 10 caracteres');return}if(mode==='edit'&&(Number(amount)<=0||!description.trim())){setError('Monto y descripcion son obligatorios');return}setBusy(true);try{if(mode==='edit')await updateCorporateCashMovement(movement.movementId,Number(amount),description.trim(),cleanReason);else await voidCorporateCashMovement(movement.movementId,cleanReason);await saved()}catch(err){setError(err instanceof Error?err.message:'No fue posible guardar la correccion')}finally{setBusy(false)}};return <div className="modal-backdrop"><form className="product-dialog small-dialog card" onSubmit={submit}><div className="dialog-head"><div><h3>{mode==='edit'?'Editar movimiento manual':'Anular movimiento manual'}</h3><p>{movement.branchName} / {movement.kind==='income'?'Ingreso':'Retiro'} / {money(movement.amount)}</p></div><button type="button" onClick={close}><X/></button></div><div className="dialog-grid one">{mode==='edit'&&<><label>Monto (Q)<input autoFocus required type="number" min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></label><label>Descripcion<input required value={description} onChange={e=>setDescription(e.target.value)}/></label></>}<label>Motivo obligatorio<textarea required minLength={10} value={reason} onChange={e=>setReason(e.target.value)} placeholder="Explica la correccion para auditoria"/></label><div className="tenant-security-note"><AlertTriangle/><span><b>Auditoria obligatoria</b>{mode==='edit'?'Se conservaran los valores anteriores y nuevos.':'El movimiento quedara anulado logicamente, sin borrado fisico.'}</span></div></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className={mode==='void'?'danger':'primary'} disabled={busy}>{busy?'Guardando...':mode==='edit'?'Guardar correccion':'Anular movimiento'}</button></div></form></div>}
function ControlMovements({profile}:{profile:StoreProfile}){const [rows,setRows]=useState<ControlMovement[]>([]);const [branches,setBranches]=useState<Branch[]>([]);const [branch,setBranch]=useState('');const [days,setDays]=useState('30');const [q,setQ]=useState('');const [loading,setLoading]=useState(true);const [error,setError]=useState('');const refresh=async()=>{setLoading(true);try{const to=new Date();const from=new Date();from.setDate(from.getDate()-Number(days));const [moves,b]=await Promise.all([loadControlMovements(from,to,branch||undefined),loadBranches(profile)]);setRows(moves);setBranches(b);setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar movimientos')}finally{setLoading(false)}};useEffect(()=>{refresh()},[branch,days]);const shown=rows.filter(r=>(r.description+' '+r.userName+' '+r.type).toLowerCase().includes(q.toLowerCase()));return <><div className="hub-section-head"><div><h3>Movimientos de todas las sucursales</h3><p>Ventas, compras, devoluciones, anulaciones e ingresos o retiros de caja.</p></div><button className="secondary" onClick={refresh}><RefreshCw/>Actualizar</button></div><div className="movement-filters card"><div className="search-box"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar movimiento o usuario..."/></div><select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select><select value={days} onChange={e=>setDays(e.target.value)}><option value="7">Últimos 7 días</option><option value="30">Últimos 30 días</option><option value="90">Últimos 90 días</option></select></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<section className="card movement-table">{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Cargando movimientos…</b></div>:<div className="table-scroll"><table><thead><tr><th>Fecha y hora</th><th>Sucursal</th><th>Tipo</th><th>Descripción</th><th>Usuario</th><th>Monto</th></tr></thead><tbody>{shown.map(r=><tr key={`${r.type}-${r.id}`}><td>{new Date(r.date).toLocaleString('es-GT')}</td><td><b>{r.branchName}</b></td><td><span className={`movement-type ${r.type.toLowerCase().replaceAll(' ','-')}`}>{r.type}</span></td><td>{r.description}</td><td>{r.userName}</td><td className={r.amount<0?'negative-text':'positive-text'}>{money(r.amount)}</td></tr>)}</tbody></table>{shown.length===0&&<div className="empty-table"><Search/><b>Sin movimientos para mostrar</b></div>}</div>}</section></>}

function CashClosureReports({profile}:{profile:StoreProfile}){const [rows,setRows]=useState<CashClosureReport[]>([]);const [branches,setBranches]=useState<Branch[]>([]);const [branch,setBranch]=useState('');const [days,setDays]=useState('7');const [selected,setSelected]=useState<CashClosureReport|null>(null);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const refresh=async()=>{setLoading(true);try{const to=new Date();const from=new Date();from.setDate(from.getDate()-Number(days));const [r,b]=await Promise.all([loadCashClosureReports(from,to,branch||undefined),loadBranches(profile)]);setRows(r);setBranches(b);setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar cierres de caja')}finally{setLoading(false)}};useEffect(()=>{refresh()},[branch,days]);const totals=rows.reduce((a,r)=>({sales:a.sales+r.totalSales,cash:a.cash+r.cashSales,diff:a.diff+r.difference,refunds:a.refunds+r.refunds}),{sales:0,cash:0,diff:0,refunds:0});return <><div className="hub-section-head"><div><h3>Reportes diarios de cierre de caja</h3><p>Revisa cada cierre por sucursal, cajero y diferencia de efectivo.</p></div><button className="secondary" onClick={refresh}><RefreshCw/>Actualizar</button></div><div className="inventory-control-stats"><MiniStat label="Cierres" value={String(rows.length)} icon={ReceiptText}/><MiniStat label="Ventas cerradas" value={money(totals.sales)} icon={CircleDollarSign}/><MiniStat label="Efectivo" value={money(totals.cash)} icon={Banknote}/><MiniStat label="Diferencia" value={money(totals.diff)} icon={AlertTriangle} warn={Math.abs(totals.diff)>0}/></div><div className="movement-filters card"><select value={branch} onChange={e=>setBranch(e.target.value)}><option value="">Todas las sucursales</option>{branches.map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select><select value={days} onChange={e=>setDays(e.target.value)}><option value="1">Hoy / ultimas 24 horas</option><option value="7">Ultimos 7 dias</option><option value="30">Ultimos 30 dias</option><option value="90">Ultimos 90 dias</option></select></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<section className="card movement-table">{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Cargando cierres...</b></div>:<div className="table-scroll"><table><thead><tr><th>Cierre</th><th>Sucursal</th><th>Cajero</th><th>Ventas</th><th>Efectivo esperado</th><th>Contado</th><th>Diferencia</th><th>Acciones</th></tr></thead><tbody>{rows.map(r=><tr key={r.sessionId}><td>{new Date(r.closedAt).toLocaleString('es-GT')}</td><td><b>{r.branchName}</b><span className="subline">Apertura {new Date(r.openedAt).toLocaleString('es-GT')}</span></td><td>{r.userName}</td><td><b>{money(r.totalSales)}</b></td><td>{money(r.expectedAmount)}</td><td>{money(r.closingAmount)}</td><td className={Math.abs(r.difference)>0?'negative-text':'positive-text'}>{money(r.difference)}</td><td><button className="secondary" onClick={()=>setSelected(r)}><Eye/>Abrir</button></td></tr>)}</tbody></table>{rows.length===0&&<div className="empty-table"><ReceiptText/><b>No hay cierres en este periodo</b></div>}</div>}</section>{selected&&<CashClosureDetail report={selected} close={()=>setSelected(null)}/>}</>}
function CashClosureDetail({report,close}:{report:CashClosureReport;close:()=>void}){const [movements,setMovements]=useState(report.movements??[]);const [loading,setLoading]=useState(false);const [error,setError]=useState('');useEffect(()=>{let alive=true;setLoading(true);loadCashClosureMovements(report.sessionId).then(rows=>{if(alive)setMovements(rows)}).catch(e=>{if(alive)setError(e instanceof Error?e.message:'No fue posible cargar movimientos')}).finally(()=>{if(alive)setLoading(false)});return()=>{alive=false}},[report.sessionId]);const print=()=>printCashClosureReport({...report,movements});return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div className="product-dialog small-dialog card"><div className="dialog-head"><div><h3>Cierre de caja</h3><p>{report.branchName} ? {new Date(report.closedAt).toLocaleString('es-GT')}</p></div><button type="button" onClick={close}><X/></button></div><div className="cash-summary"><div><span>Responsable</span><b>{report.userName}</b></div><div><span>Fondo inicial</span><b>{money(report.openingAmount)}</b></div><div><span>Ventas efectivo</span><b>{money(report.cashSales)}</b></div><div><span>Ventas tarjeta</span><b>{money(report.cardSales)}</b></div><div><span>Transferencias</span><b>{money(report.transferSales)}</b></div><div><span>Devoluciones</span><b>{money(report.refunds)}</b></div><div><span>Ingresos manuales</span><b>{money(report.manualIncome)}</b></div><div><span>Retiros</span><b>{money(report.manualExpense)}</b></div><div><span>Movimientos</span><b>{loading?'Cargando...':String(movements.length)}</b></div><div><span>Esperado</span><b>{money(report.expectedAmount)}</b></div><div><span>Contado</span><b>{money(report.closingAmount)}</b></div><div><span>Diferencia</span><b className={Math.abs(report.difference)>0?'negative-text':'positive-text'}>{money(report.difference)}</b></div></div>{error&&<div className="auth-message error">{error}</div>}<div className="dialog-actions"><button type="button" className="secondary" onClick={close}>Cerrar</button><button className="primary" disabled={loading} onClick={print}><ReceiptText/>Imprimir reporte</button></div></div></div>}
function ControlInventoryMatrix(){const [rows,setRows]=useState<ControlInventory[]>([]);const [q,setQ]=useState('');const [loading,setLoading]=useState(true);const [error,setError]=useState('');const refresh=async()=>{setLoading(true);try{setRows(await loadControlInventory());setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar inventario')}finally{setLoading(false)}};useEffect(()=>{refresh()},[]);const shown=rows.filter(r=>(r.productName+r.sku+r.category).toLowerCase().includes(q.toLowerCase()));const branchNames=Array.from(new Set(rows.flatMap(r=>Object.keys(r.stockByBranch)))).sort();const totalValue=rows.reduce((n,r)=>n+r.inventoryValue,0);return <><div className="hub-section-head"><div><h3>Inventario consolidado</h3><p>Existencias de cada producto en todas las sucursales.</p></div><button className="secondary" onClick={refresh}><RefreshCw/>Actualizar</button></div><div className="inventory-control-stats"><MiniStat label="Productos" value={String(rows.length)} icon={Package}/><MiniStat label="Valor total" value={money(totalValue)} icon={CircleDollarSign}/><MiniStat label="Sucursales" value={String(branchNames.length)} icon={Store}/></div><div className="search-box inventory-search"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar producto, SKU o categoría..."/></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<section className="card inventory-matrix">{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Consolidando inventario…</b></div>:<div className="table-scroll"><table><thead><tr><th>Producto</th><th>Categoría</th>{branchNames.map(b=><th key={b}>{b}</th>)}<th>Total</th><th>Valor</th></tr></thead><tbody>{shown.map(r=><tr key={r.productId}><td><b>{r.productName}</b><span className="subline">{r.sku}</span></td><td><span className="category-tag">{r.category}</span></td>{branchNames.map(b=>{const stock=Number(r.stockByBranch[b]??0);return <td key={b}><span className={stock<=0?'stock-matrix empty':stock<=r.minStock?'stock-matrix low':'stock-matrix'}>{stock}</span></td>})}<td><b>{r.totalStock}</b></td><td>{money(r.inventoryValue)}</td></tr>)}</tbody></table></div>}</section></>}

function ControlCenter({profile}:{profile:StoreProfile|null}){const [period,setPeriod]=useState<'7'|'30'|'month'>('month');const [rows,setRows]=useState<BranchReport[]>([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const range=useMemo(()=>{const to=new Date();const from=new Date();if(period==='7')from.setDate(from.getDate()-7);else if(period==='30')from.setDate(from.getDate()-30);else{from.setDate(1);from.setHours(0,0,0,0)}return {from,to}},[period]);const refresh=async()=>{if(!profile)return;setLoading(true);try{setRows(await loadBranchControl(range.from,range.to));setError('')}catch(e){setError(e instanceof Error?e.message:'No fue posible cargar el reporte')}finally{setLoading(false)}};useEffect(()=>{refresh()},[profile,period]);const totals=rows.reduce((a,r)=>({sales:a.sales+r.netSales,refunds:a.refunds+r.refunds,profit:a.profit+r.grossProfit,tx:a.tx+r.transactions,inventory:a.inventory+r.inventoryValue}),{sales:0,refunds:0,profit:0,tx:0,inventory:0});const exportCsv=()=>{const header='Sucursal,Ventas netas,Devoluciones,Transacciones,Ticket promedio,Utilidad,Margen,Inventario,Stock bajo,Agotados';const body=rows.map(r=>[r.branchName,r.netSales,r.refunds,r.transactions,r.averageTicket,r.grossProfit,r.margin,r.inventoryValue,r.lowStock,r.outOfStock].join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([header+'\n'+body],{type:'text/csv'}));a.download=`reporte-sucursales-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)};return <><div className="page-intro control-intro"><div><h2>Centro de control</h2><p>Vista consolidada de todas las sucursales de {profile?.businessName}.</p></div><div className="control-actions"><div className="period-tabs">{[['7','7 días'],['30','30 días'],['month','Este mes']].map(([v,l])=><button className={period===v?'active':''} onClick={()=>setPeriod(v as any)} key={v}>{l}</button>)}</div><button className="secondary" onClick={exportCsv}><Download/>Exportar</button></div></div>{error&&<div className="system-alert"><AlertTriangle/>{error}</div>}<div className="metric-grid"><Metric label="Ventas netas" value={money(totals.sales)} change="Todas las tiendas" up icon={CircleDollarSign}/><Metric label="Transacciones" value={String(totals.tx)} change="Consolidadas" up icon={ReceiptText}/><Metric label="Utilidad bruta" value={money(totals.profit)} change={`${totals.sales?((totals.profit/totals.sales)*100).toFixed(1):0}% margen`} up={totals.profit>=0} icon={BarChart3}/><Metric label="Valor de inventario" value={money(totals.inventory)} change="Todas las tiendas" up icon={Boxes}/></div><section className="card control-chart"><CardHead title="Comparativo de sucursales" sub="Ventas netas y utilidad bruta" action={<button className="icon-btn" onClick={refresh}><RefreshCw/></button>}/><div className="chart-wrap tall"><ResponsiveContainer width="100%" height="100%"><BarChart data={rows} margin={{left:10,right:15}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#eceeea"/><XAxis dataKey="branchName" axisLine={false} tickLine={false} tick={{fontSize:10}}/><YAxis axisLine={false} tickLine={false} tickFormatter={v=>`Q${Math.round(v/1000)}k`}/><Tooltip formatter={(v)=>money(Number(v))}/><Bar dataKey="netSales" name="Ventas netas" fill="#278d57" radius={[5,5,0,0]}/><Bar dataKey="grossProfit" name="Utilidad" fill="#c9f45c" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></section><section className="card branch-matrix"><CardHead title="Matriz de rendimiento" sub={`${rows.length} sucursales · ${range.from.toLocaleDateString('es-GT')} al ${range.to.toLocaleDateString('es-GT')}`}/>{loading?<div className="empty-table"><RefreshCw className="spin"/><b>Calculando resultados…</b></div>:<div className="table-scroll"><table><thead><tr><th>Sucursal</th><th>Ventas netas</th><th>Devoluciones</th><th>Transacciones</th><th>Ticket prom.</th><th>Utilidad</th><th>Margen</th><th>Inventario</th><th>Alertas</th></tr></thead><tbody>{rows.map((r,i)=><tr key={r.branchId}><td><div className="matrix-branch"><span>{i+1}</span><div><b>{r.branchName}</b><small>{r.active?'Activa':'Inactiva'}</small></div></div></td><td><b>{money(r.netSales)}</b></td><td className={r.refunds>0?'negative-text':''}>{money(r.refunds)}</td><td>{r.transactions}</td><td>{money(r.averageTicket)}</td><td className={r.grossProfit>=0?'positive-text':'negative-text'}>{money(r.grossProfit)}</td><td><span className={r.margin>=25?'margin good':r.margin>=10?'margin':'margin bad'}>{r.margin.toFixed(1)}%</span></td><td>{money(r.inventoryValue)}</td><td><div className="alert-counts"><span className={r.lowStock?'warn':''}>{r.lowStock} bajos</span><span className={r.outOfStock?'bad':''}>{r.outOfStock} agotados</span></div></td></tr>)}</tbody><tfoot><tr><td><b>TOTAL</b></td><td><b>{money(totals.sales)}</b></td><td>{money(totals.refunds)}</td><td><b>{totals.tx}</b></td><td>{money(totals.tx?totals.sales/totals.tx:0)}</td><td><b>{money(totals.profit)}</b></td><td>{totals.sales?((totals.profit/totals.sales)*100).toFixed(1):0}%</td><td><b>{money(totals.inventory)}</b></td><td/></tr></tfoot></table></div>}</section></>}

function POS({catalog,profile,refresh}:{catalog:Product[];profile:StoreProfile|null;refresh:()=>Promise<void>}){const [cart,setCart]=useState<CartItem[]>([]); const [query,setQuery]=useState(''); const [cat,setCat]=useState('Todos'); const [pay,setPay]=useState<'Efectivo'|'Tarjeta'|'Transferencia'>('Efectivo'); const [paid,setPaid]=useState(false); const [receipt,setReceipt]=useState<ReceiptData|null>(null); const [charging,setCharging]=useState(false); const [chargeError,setChargeError]=useState('')
 const filtered=catalog.filter(p=>(cat==='Todos'||p.category===cat)&&p.name.toLowerCase().includes(query.toLowerCase())); const subtotal=cart.reduce((s,p)=>s+p.price*p.quantity,0); const tax=0; const total=subtotal+tax
 const add=(p:Product)=>setCart(c=>{const found=c.find(i=>i.id===p.id);if((found?.quantity??0)>=p.stock)return c;return found?c.map(i=>i.id===p.id?{...i,quantity:i.quantity+1}:i):[...c,{...p,quantity:1}]}); const qty=(id:string,d:number)=>setCart(c=>c.map(i=>i.id===id?{...i,quantity:Math.max(1,Math.min(i.stock,i.quantity+d))}:i));
 const checkout=async()=>{if(!profile||!cart.length)return;setCharging(true);setChargeError('');try{const sale=await api.sales.checkout({businessId:profile.businessId,branchId:profile.branchId,cashierId:profile.id,items:cart.map(i=>({product_id:i.id,product_name:i.name,quantity:i.quantity,unit_cost:i.cost,unit_price:i.price,discount:0,tax:0,total:i.price*i.quantity})),payments:[{method:pay==='Efectivo'?'cash':pay==='Tarjeta'?'card':'transfer',amount:total}]});setReceipt({businessName:profile.businessName,taxId:profile.taxId,businessPhone:profile.businessPhone,branchName:profile.branchName,branchAddress:profile.branchAddress,branchPhone:profile.branchPhone,saleNumber:sale.number,cashier:profile.fullName,date:sale.created_at??new Date(),paymentMethod:pay,subtotal,discount:0,tax,total,lines:cart.map(i=>({name:i.name,quantity:i.quantity,unitPrice:i.price,total:i.price*i.quantity}))});await refresh();setPaid(true)}catch(e){setChargeError(e instanceof Error?e.message:'No fue posible completar la venta')}finally{setCharging(false)}}
 if(paid)return <div className="success-screen card"><div className="success-icon"><CheckCircle2 size={44}/></div><h2>¡Venta completada!</h2><p>La venta <b>#{String(receipt?.saleNumber??'').padStart(5,'0')}</b> fue registrada correctamente.</p><strong>{money(total)}</strong><label className="paper-choice">Papel <select defaultValue={localStorage.getItem('receipt-paper')||'80mm'} onChange={e=>localStorage.setItem('receipt-paper',e.target.value)}><option value="80mm">80 mm</option><option value="58mm">58 mm</option></select></label><div><button className="secondary" onClick={()=>receipt&&printThermalReceipt(receipt)}><ReceiptText size={18}/>Imprimir ticket</button><button className="primary" onClick={()=>{setPaid(false);setReceipt(null);setCart([])}}><Plus size={18}/>Nueva venta</button></div></div>
 return <div className="pos-layout"><section className="pos-products"><div className="pos-search"><Search/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar producto por nombre o código..."/><button><ScanBarcode size={20}/>Escanear</button></div><div className="category-chips">{['Todos','Bebidas','Granos','Lácteos','Snacks','Hogar'].map(c=><button key={c} className={cat===c?'active':''} onClick={()=>setCat(c)}>{c}</button>)}</div><div className="product-grid">{filtered.map(p=><button className="product-card" key={p.id} onClick={()=>add(p)}><ProductThumb p={p} big/><div className="product-copy"><strong>{p.name}</strong><span>{p.unit}</span><div><b>{money(p.price)}</b><em className={p.stock<=p.minStock?'low':''}>{p.stock} disp.</em></div></div><span className="add-product"><Plus size={18}/></span></button>)}</div></section>
 <aside className="cart-panel"><div className="cart-title"><div><h2>Venta actual</h2><span>{cart.reduce((s,i)=>s+i.quantity,0)} productos</span></div><button onClick={()=>setCart([])}><Trash2 size={18}/></button></div><button className="customer-select"><div><UserRound size={18}/><span><small>Cliente</small><b>Consumidor final</b></span></div><ChevronDown size={17}/></button><div className="cart-items">{cart.length===0?<div className="empty-cart"><ShoppingCart/><b>Tu carrito está vacío</b><span>Agrega productos para comenzar</span></div>:cart.map(i=><div className="cart-item" key={i.id}><ProductThumb p={i}/><div className="cart-item-main"><strong>{i.name}</strong><span>{money(i.price)} c/u</span><div className="stepper"><button onClick={()=>qty(i.id,-1)}><Minus/></button><b>{i.quantity}</b><button onClick={()=>qty(i.id,1)}><Plus/></button></div></div><div className="cart-item-price"><b>{money(i.price*i.quantity)}</b><button onClick={()=>setCart(c=>c.filter(x=>x.id!==i.id))}><X/></button></div></div>)}</div><div className="cart-bottom"><div className="totals"><p><span>Subtotal</span><b>{money(subtotal)}</b></p><p><span>Impuestos</span><b>{money(tax)}</b></p><p className="grand"><span>Total</span><b>{money(total)}</b></p></div><label className="payment-label">Método de pago</label><div className="pay-methods">{([['Efectivo',Banknote],['Tarjeta',CreditCard],['Transferencia',RefreshCw]] as const).map(([m,I])=><button className={pay===m?'active':''} onClick={()=>setPay(m)} key={m}><I/><span>{m}</span></button>)}</div>{chargeError&&<div className="auth-message error">{chargeError}</div>}<button className="charge" disabled={!cart.length||charging||!profile} onClick={checkout}><span>{charging?'Procesando…':'Cobrar'}</span><b>{money(total)}</b></button><p className="shortcut">Presiona <kbd>F2</kbd> para cobrar</p></div></aside></div>}

function Products({catalog,profile,refresh}:{catalog:Product[];profile:StoreProfile|null;refresh:()=>Promise<void>}){
  const [q,setQ]=useState(''); const [open,setOpen]=useState(false)
  const rows=catalog.filter(p=>p.name.toLowerCase().includes(q.toLowerCase())||p.sku.toLowerCase().includes(q.toLowerCase()))
  const low=catalog.filter(p=>p.stock<=p.minStock).length
  return <><PageIntro title="Productos e inventario" text="Controla existencias, precios y movimientos de tus productos." button="Nuevo producto" onAction={()=>setOpen(true)}/><div className="inventory-stats"><MiniStat label="Productos activos" value={String(catalog.length)} icon={Package}/><MiniStat label="Valor del inventario" value={money(catalog.reduce((s,p)=>s+p.cost*p.stock,0))} icon={Boxes}/><MiniStat label="Stock bajo" value={`${low} productos`} icon={AlertTriangle} warn/><MiniStat label="Sin existencias" value={`${catalog.filter(p=>p.stock<=0).length} productos`} icon={X}/></div><section className="card table-card"><div className="table-tools"><div className="search-box"><Search/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Buscar producto, SKU o código..."/></div><button className="secondary"><ListFilter/>Filtros</button><button className="secondary"><Download/>Exportar</button></div>{rows.length===0?<div className="empty-table"><Package/><b>Aún no hay productos</b><span>Crea tu primer producto para comenzar a vender.</span><button className="primary" onClick={()=>setOpen(true)}><Plus/>Nuevo producto</button></div>:<div className="table-scroll"><table><thead><tr><th>Producto</th><th>SKU / Código</th><th>Categoría</th><th>Precio</th><th>Costo</th><th>Existencias</th><th>Estado</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td><div className="product-cell"><ProductThumb p={p}/><div><b>{p.name}</b><span>{p.unit}</span></div></div></td><td><b className="mono">{p.sku}</b><span className="subline">{p.barcode}</span></td><td><span className="category-tag">{p.category}</span></td><td><b>{money(p.price)}</b></td><td>{money(p.cost)}</td><td><div className="inventory-count"><b>{p.stock}</b><div className="progress"><i style={{width:`${Math.min(100,p.stock/40*100)}%`}}/></div></div></td><td><span className={p.stock<=p.minStock?'badge warning':'badge success'}>{p.stock<=p.minStock?'Stock bajo':'Disponible'}</span></td></tr>)}</tbody></table></div>}</section>{open&&profile&&<ProductDialog profile={profile} close={()=>setOpen(false)} saved={async()=>{await refresh();setOpen(false)}}/>}</>
}

